input.content:
// ─────────────────────────────────────────────────────────────
//  CHIMERA — procedural creature art
//  Everything is drawn with the 2D canvas. No image assets.
// ─────────────────────────────────────────────────────────────

const TAU = Math.PI * 2

function hexToRgb(hex) {
  let h = hex.replace('#', '')
  if (h.length === 3) h = h.split('').map(c => c + c).join('')
  const n = parseInt(h, 16)
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255]
}
function rgbToHex(r, g, b) {
  return '#' + [r, g, b].map(v => Math.max(0, Math.min(255, Math.round(v))).toString(16).padStart(2, '0')).join('')
}
export function mix(a, b, t) {
  const A = hexToRgb(a), B = hexToRgb(b)
  return rgbToHex(A[0] + (B[0] - A[0]) * t, A[1] + (B[1] - A[1]) * t, A[2] + (B[2] - A[2]) * t)
}
export function shade(hex, amt) {
  return amt < 0 ? mix(hex, '#000000', -amt) : mix(hex, '#ffffff', amt)
}
export function rgba(hex, a) {
  const [r, g, b] = hexToRgb(hex)
  return `rgba(${r},${g},${b},${a})`
}

function ell(ctx, x, y, rx, ry, rot = 0) {
  ctx.beginPath()
  ctx.ellipse(x, y, rx, ry, rot, 0, TAU)
}
function poly(ctx, pts, close = true) {
  ctx.beginPath()
  pts.forEach((p, i) => i ? ctx.lineTo(p[0], p[1]) : ctx.moveTo(p[0], p[1]))
  if (close) ctx.closePath()
}
function curve(ctx, pts) {
  ctx.beginPath()
  ctx.moveTo(pts[0][0], pts[0][1])
  for (let i = 1; i < pts.length - 1; i++) {
    const xc = (pts[i][0] + pts[i + 1][0]) / 2
    const yc = (pts[i][1] + pts[i + 1][1]) / 2
    ctx.quadraticCurveTo(pts[i][0], pts[i][1], xc, yc)
  }
  const last = pts[pts.length - 1]
  ctx.lineTo(last[0], last[1])
}
function bodyGrad(ctx, color, accent, y0, y1) {
  const g = ctx.createLinearGradient(0, y0, 0, y1)
  g.addColorStop(0, mix(color, '#ffffff', 0.18))
  g.addColorStop(0.45, color)
  g.addColorStop(1, shade(color, -0.38))
  return g
}

// ─────────── shared adornments ───────────

function drawWings(ctx, pal, t, kind = 'avian', alpha = 1) {
  const flap = Math.sin(t * 3.1) * 0.12
  ctx.save()
  ctx.globalAlpha *= alpha
  for (const side of [-1, 1]) {
    ctx.save()
    ctx.rotate(side * (0.08 + flap))
    const grad = ctx.createLinearGradient(-10, -80, -55, -30)
    grad.addColorStop(0, rgba(pal.accent, 0.85))
    grad.addColorStop(1, rgba(pal.deep, 0.9))
    if (kind === 'avian') {
      poly(ctx, [[-4, -62], [-58, -92], [-48, -63], [-62, -58], [-38, -46], [-20, -44]])
      ctx.fillStyle = grad
      ctx.fill()
      ctx.strokeStyle = rgba(pal.accent, 0.65)
      ctx.lineWidth = 1.1
      ctx.stroke()
      // feather lines
      ctx.strokeStyle = rgba(pal.soft, 0.32)
      ctx.lineWidth = 0.8
      for (let i = 0; i < 4; i++) {
        ctx.beginPath()
        ctx.moveTo(-12 - i * 4, -58 + i * 2)
        ctx.quadraticCurveTo(-40 - i * 4, -72 + i * 3, -54 + i * 3, -62 + i * 5)
        ctx.stroke()
      }
    } else {
      // leathery wing
      poly(ctx, [[-6, -66], [-48, -100], [-72, -79], [-58, -66], [-70, -48], [-40, -42], [-20, -40]])
      ctx.fillStyle = grad
      ctx.fill()
      ctx.strokeStyle = rgba(pal.accent, 0.8)
      ctx.lineWidth = 1.2
      ctx.stroke()
      ctx.strokeStyle = rgba(pal.deep, 0.9)
      for (const end of [[-66, -80], [-56, -58], [-38, -44]]) {
        ctx.beginPath(); ctx.moveTo(-12, -62); ctx.lineTo(end[0], end[1]); ctx.stroke()
      }
    }
    ctx.restore()
  }
  ctx.restore()
}

function drawHorns(ctx, pal, size = 1) {
  ctx.save()
  ctx.fillStyle = mix(pal.accent, '#f8e6c0', 0.35)
  ctx.strokeStyle = rgba(pal.deep, 0.9)
  ctx.lineWidth = 1
  for (const side of [-1, 1]) {
    ctx.beginPath()
    ctx.moveTo(20 + side * 6, -82 * size)
    ctx.quadraticCurveTo(36 + side * 16, -102 * size, 28 + side * 26, -104 * size)
    ctx.quadraticCurveTo(28 + side * 8, -90 * size, 30 + side * 6, -78 * size)
    ctx.closePath()
    ctx.fill(); ctx.stroke()
  }
  ctx.restore()
}

function drawSpikes(ctx, pal, y = -66, count = 5, color) {
  ctx.save()
  ctx.fillStyle = color || mix(pal.accent, pal.deep, 0.35)
  for (let i = 0; i < count; i++) {
    const x = -26 + i * 14
    const h = 11 + Math.sin(i * 1.7) * 5
    poly(ctx, [[x - 4, y], [x, y - h], [x + 4, y]])
    ctx.fill()
  }
  ctx.restore()
}

function drawOrbs(ctx, pal, t, n = 4) {
  ctx.save()
  ctx.globalCompositeOperation = 'lighter'
  for (let i = 0; i < n; i++) {
    const a = t * 0.7 + i * (TAU / n)
    const x = Math.cos(a) * (36 + i * 4)
    const y = -48 + Math.sin(a * 1.4) * 22
    const r = 2 + Math.sin(t * 2 + i) * 1.2
    const g = ctx.createRadialGradient(x, y, 0, x, y, r * 4)
    g.addColorStop(0, rgba(pal.accent, 0.9))
    g.addColorStop(1, rgba(pal.accent, 0))
    ctx.fillStyle = g
    ell(ctx, x, y, r * 4, r * 4); ctx.fill()
  }
  ctx.restore()
}

function drawShards(ctx, pal, t) {
  ctx.save()
  for (let i = 0; i < 4; i++) {
    const a = t * 0.5 + i * (TAU / 4)
    const x = Math.cos(a) * 34
    const y = -52 + Math.sin(a + 0.8) * 24
    ctx.save()
    ctx.translate(x, y)
    ctx.rotate(a * 1.3)
    poly(ctx, [[0, -5], [4, 0], [0, 5], [-4, 0]])
    ctx.fillStyle = rgba(pal.accent, 0.8)
    ctx.fill()
    ctx.strokeStyle = rgba(pal.soft, 0.5)
    ctx.stroke()
    ctx.restore()
  }
  ctx.restore()
}

function drawTendrils(ctx, pal, t, n = 4, from = [-6, -26], length = 34) {
  ctx.save()
  ctx.lineCap = 'round'
  for (let i = 0; i < n; i++) {
    const sway = Math.sin(t * 1.7 + i * 1.2) * 8
    const sx = from[0] + (i - n / 2) * 15
    ctx.beginPath()
    ctx.moveTo(sx, from[1])
    ctx.bezierCurveTo(sx - 12 + sway, -4, sx - 26 - sway, 10, sx - 18 + sway, 26 + i * 2)
    ctx.strokeStyle = i === 0 ? rgba(pal.accent, 0.65) : rgba(pal.color, 0.38)
    ctx.lineWidth = 7 - i
    ctx.stroke()
  }
  ctx.restore()
}

function drawEyes(ctx, x, y, spread, color = '#ffe9a8', size = 2.2, glow = true) {
  ctx.save()
  if (glow) {
    ctx.shadowColor = color
    ctx.shadowBlur = 8
  }
  ctx.fillStyle = color
  ell(ctx, x - spread, y, size, size * 0.7); ctx.fill()
  ell(ctx, x + spread, y, size, size * 0.7); ctx.fill()
  ctx.restore()
}

// ─────────── silhouettes ───────────

function drawBeast(ctx, pal, t, moving, atk, walk) {
  const leg = moving ? Math.sin(walk) * 4 : 0
  const leg2 = moving ? Math.sin(walk + Math.PI) * 4 : 0
  const bob = Math.sin(t * 2.2) * 1.4

  // tail
  ctx.save()
  ctx.translate(0, bob)
  ctx.beginPath()
  ctx.moveTo(-28, -48)
  ctx.quadraticCurveTo(-55, -62, -58, -78 + Math.sin(t * 2) * 4)
  ctx.strokeStyle = pal.color
  ctx.lineWidth = 9
  ctx.lineCap = 'round'
  ctx.stroke()
  ctx.strokeStyle = rgba(pal.soft, 0.6)
  ctx.lineWidth = 3
  ctx.stroke()
  ctx.restore()

  // back legs
  ctx.strokeStyle = shade(pal.color, -0.25)
  ctx.lineWidth = 7
  ctx.lineCap = 'round'
  for (const [x, ph] of [[-20, leg2], [14, leg]]) {
    ctx.beginPath()
    ctx.moveTo(x, -30)
    ctx.quadraticCurveTo(x - 3 + ph, -14, x + ph, 2)
    ctx.stroke()
  }

  // body
  ctx.save()
  ctx.translate(0, bob)
  const grad = bodyGrad(ctx, pal.color, pal.accent, -76, -20)
  ell(ctx, 0, -50, 34, 23, -0.08)
  ctx.fillStyle = grad
  ctx.fill()
  ctx.strokeStyle = rgba(pal.deep, 0.65)
  ctx.lineWidth = 1.4
  ctx.stroke()

  // belly
  ell(ctx, 3, -38, 25, 10, -0.05)
  ctx.fillStyle = rgba(pal.soft, 0.16); ctx.fill()

  // flank markings
  ctx.strokeStyle = rgba(pal.accent, 0.7)
  ctx.lineWidth = 2
  ctx.beginPath()
  ctx.moveTo(-18, -58); ctx.quadraticCurveTo(0, -64, 18, -57)
  ctx.stroke()
  for (let i = 0; i < 3; i++) {
    ctx.beginPath()
    ctx.moveTo(-12 + i * 10, -61); ctx.lineTo(-16 + i * 10, -50)
    ctx.stroke()
  }

  // neck + head
  ctx.beginPath()
  ctx.moveTo(18, -62)
  ctx.quadraticCurveTo(28, -72, 32, -72)
  ctx.lineTo(42, -64)
  ctx.lineTo(18, -52)
  ctx.closePath()
  ctx.fillStyle = shade(pal.color, -0.08); ctx.fill()
  ctx.strokeStyle = rgba(pal.deep, 0.55); ctx.stroke()

  // ears
  ctx.fillStyle = shade(pal.color, -0.15)
  poly(ctx, [[23, -80], [27, -95], [34, -79]]); ctx.fill()
  poly(ctx, [[32, -79], [39, -92], [42, -76]]); ctx.fill()

  // head
  ell(ctx, 33, -72, 15, 13, 0.08)
  ctx.fillStyle = bodyGrad(ctx, pal.color, pal.accent, -88, -60)
  ctx.fill()
  ctx.strokeStyle = rgba(pal.deep, 0.65); ctx.stroke()

  // muzzle
  poly(ctx, [[42, -78], [55, -74], [54, -66], [41, -66]])
  ctx.fillStyle = shade(pal.color, -0.22); ctx.fill()
  ctx.strokeStyle = rgba(pal.deep, 0.6); ctx.stroke()
  ell(ctx, 52, -73, 2, 1.6)
  ctx.fillStyle = pal.deep; ctx.fill()

  // mane
  ctx.fillStyle = rgba(pal.accent, 0.8)
  for (let i = 0; i < 5; i++) {
    poly(ctx, [[10 + i * 5, -71], [15 + i * 5, -84 - Math.sin(i) * 4], [20 + i * 5, -69]])
    ctx.fill()
  }

  drawEyes(ctx, 37, -75, 3.4, mix(pal.soft, '#ffffff', 0.35), 2)
  ctx.restore()

  // front legs
  ctx.strokeStyle = shade(pal.color, -0.12)
  ctx.lineWidth = 7
  for (const [x, ph] of [[24, leg], [-8, leg2]]) {
    ctx.beginPath()
    ctx.moveTo(x, -34)
    ctx.quadraticCurveTo(x + 3 + ph, -16, x + ph, 1)
    ctx.stroke()
  }
  ctx.fillStyle = pal.accent
  for (const [x, ph] of [[-20, leg2], [14, leg], [24, leg], [-8, leg2]]) {
    ell(ctx, x + ph, 2, 5, 2.5); ctx.fill()
  }
}

function drawAvian(ctx, pal, t, moving, atk, walk) {
  const flap = Math.sin(t * 4.6) * 7
  const bob = Math.sin(t * 2.4) * 2.2
  // far wing
  ctx.save()
  ctx.globalAlpha = 0.75
  poly(ctx, [[-6, -58], [-38, -96 - flap], [-54, -72], [-30, -52]])
  ctx.fillStyle = shade(pal.accent, -0.25); ctx.fill()
  ctx.strokeStyle = rgba(pal.deep, 0.6); ctx.stroke()
  ctx.restore()

  // tail feathers
  ctx.fillStyle = shade(pal.color, -0.2)
  for (let i = 0; i < 3; i++) {
    poly(ctx, [[-12, -46 + i * 4], [-52 - i * 6, -40 + i * 4], [-44 - i * 4, -30 + i * 4]])
    ctx.fill()
    ctx.strokeStyle = rgba(pal.accent, 0.55); ctx.stroke()
  }

  // legs
  ctx.strokeStyle = mix(pal.accent, '#f4d08a', 0.5)
  ctx.lineWidth = 2.6
  ctx.beginPath(); ctx.moveTo(-2, -22); ctx.lineTo(-5, 1); ctx.stroke()
  ctx.beginPath(); ctx.moveTo(6, -22); ctx.lineTo(9, 1); ctx.stroke()
  for (const x of [-5, 9]) { ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x - 4, 3); ctx.moveTo(x, 0); ctx.lineTo(x + 4, 3); ctx.stroke() }

  ctx.save()
  ctx.translate(0, bob)
  // body
  ell(ctx, 0, -48, 24, 30, 0.15)
  ctx.fillStyle = bodyGrad(ctx, pal.color, pal.accent, -78, -20); ctx.fill()
  ctx.strokeStyle = rgba(pal.deep, 0.6); ctx.lineWidth = 1.3; ctx.stroke()

  // breast
  ell(ctx, 8, -42, 13, 17, 0.2)
  ctx.fillStyle = rgba(pal.soft, 0.25); ctx.fill()

  // head
  ell(ctx, 18, -76, 12, 11, 0.1)
  ctx.fillStyle = bodyGrad(ctx, pal.color, pal.accent, -88, -64); ctx.fill()
  ctx.strokeStyle = rgba(pal.deep, 0.6); ctx.stroke()

  // beak
  poly(ctx, [[27, -79], [41, -74], [27, -69]])
  ctx.fillStyle = mix(pal.accent, '#ffd27a', 0.55); ctx.fill()
  ctx.strokeStyle = rgba(pal.deep, 0.55); ctx.stroke()

  // crest
  ctx.strokeStyle = pal.accent
  ctx.lineWidth = 2
  for (let i = 0; i < 3; i++) {
    ctx.beginPath()
    ctx.moveTo(12 + i * 4, -86)
    ctx.quadraticCurveTo(10 + i * 6, -100 - i * 2, 2 + i * 7, -102 - i * 3)
    ctx.stroke()
  }

  drawEyes(ctx, 19, -78, 3.2, '#fff3c4', 2.1)

  // near wing, swept back
  poly(ctx, [[-8, -62], [-24, -104 - flap], [-44, -82], [-34, -56], [-10, -48]])
  const wg = ctx.createLinearGradient(0, -100, -40, -50)
  wg.addColorStop(0, rgba(pal.soft, 0.95))
  wg.addColorStop(0.55, rgba(pal.color, 0.85))
  wg.addColorStop(1, rgba(pal.accent, 0.65))
  ctx.fillStyle = wg; ctx.fill()
  ctx.strokeStyle = rgba(pal.accent, 0.8); ctx.lineWidth = 1; ctx.stroke()
  ctx.strokeStyle = rgba(pal.deep, 0.35)
  for (let i = 0; i < 3; i++) {
    ctx.beginPath()
    ctx.moveTo(-14, -58 - i * 4)
    ctx.quadraticCurveTo(-26, -76 - i * 5, -34, -88 - flap + i * 5)
    ctx.stroke()
  }
  ctx.restore()
}

function drawReptile(ctx, pal, t, moving, atk, walk) {
  const bob = Math.sin(t * 2) * 1.6
  const sway = Math.sin(t * 1.4) * 5
  // tail
  ctx.save()
  ctx.lineCap = 'round'
  ctx.beginPath()
  ctx.moveTo(-8, -22)
  ctx.bezierCurveTo(-30, -20, -50, -10, -40 + sway, 2)
  ctx.strokeStyle = shade(pal.color, -0.14); ctx.lineWidth = 13; ctx.stroke()
  ctx.strokeStyle = rgba(pal.accent, 0.55); ctx.lineWidth = 4; ctx.stroke()
  ctx.restore()

  // back spikes
  ctx.save()
  ctx.fillStyle = rgba(pal.accent, 0.85)
  for (let i = 0; i < 4; i++) {
    const y = -34 - i * 10
    poly(ctx, [[-14, y], [-24, y - 9], [-8, y - 5]])
    ctx.fill()
  }
  ctx.restore()

  // coil body
  ctx.save()
  ctx.translate(0, bob)
  ctx.beginPath()
  ctx.moveTo(0, -24)
  ctx.bezierCurveTo(-16, -36, 16, -52, 2, -64)
  ctx.strokeStyle = bodyGrad(ctx, pal.color, pal.accent, -70, -20)
  ctx.lineWidth = 26
  ctx.lineCap = 'round'
  ctx.stroke()
  ctx.strokeStyle = rgba(pal.deep, 0.5)
  ctx.lineWidth = 26
  ctx.stroke()
  ctx.strokeStyle = bodyGrad(ctx, pal.color, pal.accent, -70, -20)
  ctx.lineWidth = 23
  ctx.stroke()

  // belly plates
  ctx.strokeStyle = rgba(pal.soft, 0.35)
  ctx.lineWidth = 1.4
  for (let i = 0; i < 5; i++) {
    const y = -30 - i * 7
    ctx.beginPath(); ctx.moveTo(6, y); ctx.lineTo(14, y + 2); ctx.stroke()
  }

  // hood
  const hood = ctx.createLinearGradient(-30, -80, 20, -50)
  hood.addColorStop(0, rgba(pal.accent, 0.15))
  hood.addColorStop(1, rgba(pal.accent, 0.7))
  ctx.beginPath()
  ctx.moveTo(0, -58)
  ctx.quadraticCurveTo(-38, -76, -26, -88)
  ctx.quadraticCurveTo(2, -98, 22, -80)
  ctx.quadraticCurveTo(32, -66, 22, -58)
  ctx.closePath()
  ctx.fillStyle = hood; ctx.fill()
  ctx.strokeStyle = rgba(pal.deep, 0.6); ctx.stroke()

  // head
  ell(ctx, 15, -76, 15, 12, -0.1)
  ctx.fillStyle = bodyGrad(ctx, pal.color, pal.accent, -90, -64); ctx.fill()
  ctx.strokeStyle = rgba(pal.deep, 0.65); ctx.stroke()

  // crown scales
  ctx.fillStyle = rgba(pal.accent, 0.9)
  poly(ctx, [[4, -84], [7, -94], [12, -84]]); ctx.fill()
  poly(ctx, [[13, -85], [18, -97], [22, -84]]); ctx.fill()

  // eye
  drawEyes(ctx, 20, -79, 3.4, mix(pal.soft, '#ffffff', 0.4), 2.4)

  // tongue
  ctx.strokeStyle = '#ff6c8c'; ctx.lineWidth = 1.4; ctx.lineCap = 'round'
  const flick = (Math.sin(t * 4) + 1) * 5
  ctx.beginPath(); ctx.moveTo(28, -72); ctx.lineTo(36 + flick, -70);
  ctx.stroke()
  ctx.beginPath(); ctx.moveTo(36 + flick, -70); ctx.lineTo(40 + flick, -74); ctx.moveTo(36 + flick, -70); ctx.lineTo(41 + flick, -67); ctx.stroke()
  ctx.restore()
}

function drawTurtle(ctx, pal, t, moving, atk, walk) {
  const bob = Math.sin(t * 1.8) * 1
  // stubby legs
  ctx.strokeStyle = shade(pal.color, -0.25); ctx.lineWidth = 7; ctx.lineCap = 'round'
  for (const x of [-24, -8, 12, 26]) {
    ctx.beginPath(); ctx.moveTo(x, -14); ctx.lineTo(x + Math.sin(t * 2 + x) * 1.5, 0); ctx.stroke()
  }
  // tail
  ctx.beginPath(); ctx.moveTo(-34, -22); ctx.lineTo(-46, -14); ctx.strokeStyle = pal.color; ctx.lineWidth = 5; ctx.stroke()

  ctx.save(); ctx.translate(0, bob)
  const grad = ctx.createLinearGradient(0, -76, 0, -8)
  grad.addColorStop(0, mix(pal.color, '#fff', 0.25)); grad.addColorStop(1, shade(pal.color, -0.35))
  ctx.beginPath()
  ctx.moveTo(-34, -34)
  ctx.quadraticCurveTo(-30, -78, 2, -80)
  ctx.quadraticCurveTo(34, -78, 36, -32)
  ctx.quadraticCurveTo(22, -14, 0, -15)
  ctx.quadraticCurveTo(-22, -14, -34, -34)
  ctx.closePath()
  ctx.fillStyle = grad; ctx.fill()
  ctx.strokeStyle = rgba(pal.deep, 0.75); ctx.lineWidth = 1.6; ctx.stroke()

  // shell plates
  ctx.strokeStyle = rgba(pal.deep, 0.45); ctx.lineWidth = 1.3
  for (let i = 0; i < 4; i++) {
    ctx.beginPath()
    ctx.ellipse(0, -48, 28 - i * 4, 22 - i * 3, 0, 0, TAU)
    ctx.stroke()
  }
  ctx.beginPath(); ctx.moveTo(0, -74); ctx.lineTo(0, -22)
  ctx.moveTo(-28, -48); ctx.lineTo(28, -48); ctx.stroke()
  // rim
  ctx.beginPath(); ctx.ellipse(0, -30, 35, 9, 0, 0, TAU)
  ctx.strokeStyle = rgba(pal.accent, 0.8); ctx.lineWidth = 2; ctx.stroke()

  // head
  ctx.beginPath(); ctx.moveTo(28, -52); ctx.quadraticCurveTo(46, -52, 46, -40); ctx.quadraticCurveTo(44, -32, 28, -34); ctx.closePath()
  ctx.fillStyle = mix(pal.color, pal.accent, 0.25); ctx.fill(); ctx.strokeStyle = rgba(pal.deep, 0.6); ctx.stroke()
  drawEyes(ctx, 39, -43, 2.6, '#fff2b8', 1.7)
  // rim runes
  ctx.fillStyle = rgba(pal.soft, 0.5)
  for (let i = -2; i <= 2; i++) { ell(ctx, i * 9, -31, 1.5, 2.2); ctx.fill() }
  ctx.restore()
}

function drawInsect(ctx, pal, t, moving, atk, walk) {
  const bob = Math.sin(t * 3.4) * 2
  const step = moving ? Math.sin(t * 12) * 3 : Math.sin(t * 2) * 1
  // legs
  ctx.strokeStyle = shade(pal.color, -0.35); ctx.lineWidth = 2.2; ctx.lineCap = 'round'
  for (let i = 0; i < 3; i++) {
    const x = -10 + i * 12
    ctx.beginPath(); ctx.moveTo(x, -38); ctx.quadraticCurveTo(x - 12, -22, x - 18 + step, 0); ctx.stroke()
    ctx.beginPath(); ctx.moveTo(x + 3, -38); ctx.quadraticCurveTo(x + 10, -18, x + 12 - step, 0); ctx.stroke()
  }
  // wings
  ctx.save(); ctx.globalAlpha = 0.32
  const flap = Math.sin(t * 9) * 0.15
  for (const s of [-1, 1]) {
    ctx.save(); ctx.rotate(s * (0.2 + flap)); ctx.translate(-10, -56)
    ell(ctx, -18, 0, 26, 9, -0.35)
    ctx.fillStyle = pal.soft; ctx.fill()
    ctx.strokeStyle = rgba(pal.accent, 0.7); ctx.stroke()
    ctx.restore()
  }
  ctx.restore()

  // abdomen segments
  ctx.save(); ctx.translate(0, bob)
  for (let i = 0; i < 3; i++) {
    ell(ctx, -22 - i * 10, -42 + i * 2, 12 - i * 2, 9 - i * 1.5, 0.1)
    ctx.fillStyle = i % 2 ? shade(pal.color, -0.2) : pal.color
    ctx.fill(); ctx.strokeStyle = rgba(pal.deep, 0.6); ctx.stroke()
  }
  // thorax
  ell(ctx, 2, -46, 16, 18, -0.15)
  ctx.fillStyle = bodyGrad(ctx, pal.color, pal.accent, -66, -30); ctx.fill()
  ctx.strokeStyle = rgba(pal.deep, 0.65); ctx.stroke()

  // head
  poly(ctx, [[8, -66], [28, -76], [28, -56], [10, -48]])
  ctx.fillStyle = bodyGrad(ctx, pal.color, pal.accent, -78, -48); ctx.fill()
  ctx.strokeStyle = rgba(pal.deep, 0.6); ctx.stroke()
  // compound eyes
  ctx.save(); ctx.shadowColor = pal.accent; ctx.shadowBlur = 6
  ctx.fillStyle = mix(pal.accent, '#ffffff', 0.25)
  ell(ctx, 22, -70, 5.5, 6.5, -0.3); ctx.fill()
  ell(ctx, 20, -61, 4, 4.5, 0.3); ctx.fill()
  ctx.restore()
  // antennae
  ctx.strokeStyle = pal.accent; ctx.lineWidth = 1.4
  ctx.beginPath(); ctx.moveTo(26, -76); ctx.quadraticCurveTo(38, -94, 48, -88); ctx.stroke()
  ctx.beginPath(); ctx.moveTo(24, -77); ctx.quadraticCurveTo(32, -98, 42, -98); ctx.stroke()

  // scythe arms
  const raise = atk > 0 ? Math.sin(atk * Math.PI) * 0.7 : 0
  for (const s of [-1, 1]) {
    ctx.save()
    ctx.translate(8, -54 + s * 3)
    ctx.rotate(-0.5 - raise * s * 0.6)
    ctx.strokeStyle = mix(pal.accent, '#ffffff', 0.15); ctx.lineWidth = 3.2
    ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(22, -10); ctx.stroke()
    ctx.beginPath(); ctx.moveTo(22, -10); ctx.lineTo(46, -28); ctx.stroke()
    ctx.fillStyle = mix(pal.accent, '#ffffff', 0.35)
    poly(ctx, [[44, -30], [56, -34], [51, -21]]); ctx.fill()
    ctx.strokeStyle = rgba(pal.deep, 0.5); ctx.lineWidth = 0.8; ctx.stroke()
    ctx.restore()
  }
  // thorax marking
  ctx.fillStyle = rgba(pal.accent, 0.8)
  poly(ctx, [[0, -56], [7, -48], [0, -40], [-7, -48]]); ctx.fill()
  ctx.restore()
}

function drawConstruct(ctx, pal, t, moving, atk, walk) {
  const bob = Math.sin(t * 1.4) * 1.4
  // legs
  ctx.fillStyle = shade(pal.color, -0.3)
  for (const s of [-1, 1]) {
    ctx.fillRect(s * 14 - 5, -26, 10, 25)
    ctx.fillRect(s * 14 - 8, -4, 16, 5)
  }
  drawShards(ctx, pal, t * 0.7)
  ctx.save(); ctx.translate(0, bob)
  // body hex
  poly(ctx, [[-26, -68], [0, -82], [26, -68], [26, -38], [0, -26], [-26, -38]])
  const bg = ctx.createLinearGradient(-26, -82, 26, -26)
  bg.addColorStop(0, mix(pal.color, '#fff', 0.2)); bg.addColorStop(0.5, pal.color); bg.addColorStop(1, shade(pal.color, -0.4))
  ctx.fillStyle = bg; ctx.fill()
  ctx.strokeStyle = rgba(pal.deep, 0.8); ctx.lineWidth = 1.6; ctx.stroke()
  // rune trim
  ctx.strokeStyle = rgba(pal.accent, 0.9); ctx.lineWidth = 1.2
  poly(ctx, [[-20, -65], [0, -76], [20, -65], [20, -42], [0, -32], [-20, -42]], false); ctx.stroke()
  // core
  const cg = ctx.createRadialGradient(0, -54, 0, 0, -54, 17)
  cg.addColorStop(0, '#ffffff'); cg.addColorStop(0.25, mix(pal.accent, '#ffffff', 0.2)); cg.addColorStop(1, rgba(pal.accent, 0))
  ctx.fillStyle = cg; ell(ctx, 0, -54, 18, 18); ctx.fill()
  ctx.fillStyle = mix(pal.accent, '#ffffff', 0.5); ell(ctx, 0, -54, 3.5, 3.5); ctx.fill()
  // arms
  for (const s of [-1, 1]) {
    const swing = atk > 0 && s === 1 ? -Math.sin(atk * Math.PI) * 0.6 : 0
    ctx.save(); ctx.translate(s * 26, -62); ctx.rotate(swing)
    ctx.fillStyle = shade(pal.color, -0.18)
    ctx.fillRect(-4, 0, 9, 28)
    ctx.fillRect(-7, 24, 15, 10)
    ctx.strokeStyle = rgba(pal.deep, 0.7); ctx.strokeRect(-4, 0, 9, 28)
    ctx.restore()
  }
  // head
  poly(ctx, [[-10, -88], [10, -90], [13, -76], [0, -70], [-12, -76]])
  ctx.fillStyle = shade(pal.color, -0.08); ctx.fill()
  ctx.strokeStyle = rgba(pal.deep, 0.8); ctx.stroke()
  drawEyes(ctx, 1, -81, 4.5, mix(pal.accent, '#ffffff', 0.45), 2)
  // crown shard
  poly(ctx, [[-3, -95], [1, -106], [5, -95]])
  ctx.fillStyle = rgba(pal.accent, 0.85); ctx.fill()
  ctx.restore()
}

function drawSpirit(ctx, pal, t, moving, atk, walk) {
  const bob = Math.sin(t * 1.6) * 3
  const sway = Math.sin(t * 1.1) * 4
  // wisp tail
  ctx.save(); ctx.lineCap = 'round'
  for (let i = 0; i < 3; i++) {
    ctx.beginPath()
    ctx.moveTo(-6 + i * 6, -34)
    ctx.bezierCurveTo(-18 + i * 8 + sway, -16, -26 + i * 10 - sway, -2, -10 + i * 8 + sway, 12)
    ctx.strokeStyle = rgba(i === 1 ? pal.accent : pal.color, 0.35 - i * 0.06)
    ctx.lineWidth = 10 - i * 2.4
    ctx.stroke()
  }
  ctx.restore()

  // cloak
  ctx.save(); ctx.translate(0, bob)
  const cg = ctx.createLinearGradient(0, -92, 0, -10)
  cg.addColorStop(0, rgba(pal.color, 0.9))
  cg.addColorStop(0.6, rgba(pal.color, 0.55))
  cg.addColorStop(1, rgba(pal.accent, 0.03))
  ctx.beginPath()
  ctx.moveTo(-24, -14)
  ctx.quadraticCurveTo(-30, -58, -10, -76)
  ctx.quadraticCurveTo(2, -104, 24, -78)
  ctx.quadraticCurveTo(34, -54, 22, -16)
  ctx.quadraticCurveTo(0, -6, -24, -14)
  ctx.closePath()
  ctx.fillStyle = cg; ctx.fill()
  ctx.strokeStyle = rgba(pal.accent, 0.6); ctx.lineWidth = 1.2; ctx.stroke()

  // hood opening
  const hg = ctx.createRadialGradient(8, -66, 2, 8, -66, 22)
  hg.addColorStop(0, '#05060d'); hg.addColorStop(1, rgba(pal.deep, 0.9))
  ell(ctx, 8, -68, 17, 21, -0.1)
  ctx.fillStyle = hg; ctx.fill()
  ctx.strokeStyle = rgba(pal.accent, 0.5); ctx.stroke()

  drawEyes(ctx, 12, -69, 4.2, mix(pal.soft, '#ffffff', 0.55), 2.4)

  // crown wisps
  ctx.strokeStyle = rgba(pal.soft, 0.65); ctx.lineWidth = 1.4
  for (let i = 0; i < 4; i++) {
    ctx.beginPath()
    ctx.moveTo(-6 + i * 7, -88 - i * 2)
    ctx.quadraticCurveTo(-12 + i * 9 + sway * 0.5, -102 - i * 3, -4 + i * 8, -110 - i * 2)
    ctx.stroke()
  }
  // arm wisps
  ctx.strokeStyle = rgba(pal.color, 0.7); ctx.lineWidth = 4; ctx.lineCap = 'round'
  ctx.beginPath(); ctx.moveTo(20, -56); ctx.quadraticCurveTo(40, -52, 46, -40 + sway); ctx.stroke()
  ctx.beginPath(); ctx.moveTo(-18, -48); ctx.quadraticCurveTo(-34, -40, -38, -26 - sway); ctx.stroke()

  // rune
  ctx.fillStyle = rgba(pal.accent, 0.8)
  poly(ctx, [[0, -44], [4, -38], [0, -32], [-4, -38]]); ctx.fill()
  ctx.restore()
  drawOrbs(ctx, pal, t, 4)
}

function drawMonster(ctx, pal, t, moving, atk, walk) {
  const bob = Math.sin(t * 1.7) * 1.6
  const leg = moving ? Math.sin(t * 7) * 4 : 0
  drawWings(ctx, pal, t, 'dragon', 0.9)
  // tail
  ctx.save(); ctx.lineCap = 'round'
  ctx.beginPath()
  ctx.moveTo(-28, -44)
  ctx.bezierCurveTo(-58, -50, -66, -24, -52, -8)
  ctx.strokeStyle = shade(pal.color, -0.2); ctx.lineWidth = 12; ctx.stroke()
  ctx.strokeStyle = rgba(pal.accent, 0.5); ctx.lineWidth = 3; ctx.stroke()
  ctx.fillStyle = mix(pal.accent, pal.deep, 0.4)
  poly(ctx, [[-56, -10], [-64, -22], [-46, -18]]); ctx.fill()
  ctx.restore()

  // legs
  ctx.strokeStyle = shade(pal.color, -0.35); ctx.lineWidth = 9; ctx.lineCap = 'round'
  for (const [x, ph] of [[-18, leg], [16, -leg]]) {
    ctx.beginPath(); ctx.moveTo(x, -30); ctx.quadraticCurveTo(x - 4 + ph, -14, x + ph, 0); ctx.stroke()
    ctx.fillStyle = mix(pal.accent, '#f6d9a0', 0.3)
    for (let i = -1; i <= 1; i++) { poly(ctx, [[x + ph + i * 4, 0], [x + ph + i * 4 + 2, 4], [x + ph + i * 4 - 1, 3]]); ctx.fill() }
  }

  ctx.save(); ctx.translate(0, bob)
  // body
  ell(ctx, 0, -50, 41, 27, -0.04)
  ctx.fillStyle = bodyGrad(ctx, pal.color, pal.accent, -80, -22); ctx.fill()
  ctx.strokeStyle = rgba(pal.deep, 0.75); ctx.lineWidth = 1.6; ctx.stroke()
  // belly
  ell(ctx, 4, -36, 30, 10, -0.05)
  ctx.fillStyle = rgba(pal.soft, 0.2); ctx.fill()
  // molten cracks
  ctx.strokeStyle = rgba(pal.accent, 0.85); ctx.lineWidth = 1.4
  ctx.beginPath(); ctx.moveTo(-16, -64); ctx.lineTo(-8, -52); ctx.lineTo(-13, -42); ctx.stroke()
  ctx.beginPath(); ctx.moveTo(8, -68); ctx.lineTo(14, -58); ctx.lineTo(10, -48); ctx.stroke()
  // back spikes
  drawSpikes(ctx, pal, -72, 5, mix(pal.accent, pal.deep, 0.25))

  // neck
  ctx.beginPath()
  ctx.moveTo(20, -62)
  ctx.quadraticCurveTo(40, -78, 42, -86)
  ctx.lineTo(26, -54); ctx.closePath()
  ctx.fillStyle = shade(pal.color, -0.08); ctx.fill()
  ctx.strokeStyle = rgba(pal.deep, 0.6); ctx.stroke()

  // head
  ell(ctx, 44, -86, 20, 14, 0.12)
  ctx.fillStyle = bodyGrad(ctx, pal.color, pal.accent, -100, -72); ctx.fill()
  ctx.strokeStyle = rgba(pal.deep, 0.7); ctx.stroke()
  // jaw
  poly(ctx, [[48, -82], [68, -80], [66, -70], [46, -72]])
  ctx.fillStyle = shade(pal.color, -0.25); ctx.fill()
  ctx.strokeStyle = rgba(pal.deep, 0.6); ctx.stroke()
  // teeth
  ctx.fillStyle = '#f7ecd2'
  for (let i = 0; i < 3; i++) { poly(ctx, [[55 + i * 4, -78], [57 + i * 4, -73], [59 + i * 4, -78]]); ctx.fill() }
  // horns
  drawHorns(ctx, pal, 1)
  drawEyes(ctx, 48, -89, 4, '#ffd76e', 2.3)
  // nostril ember
  ctx.fillStyle = rgba(pal.accent, 0.9); ell(ctx, 64, -82, 1.6, 1.2); ctx.fill()
  // crown spikes
  ctx.fillStyle = rgba(pal.accent, 0.8)
  poly(ctx, [[32, -94], [36, -105], [40, -93]]); ctx.fill()
  ctx.restore()
}

function drawKraken(ctx, pal, t, moving, atk, walk) {
  const bob = Math.sin(t * 1.5) * 2
  drawTendrils(ctx, pal, t, 5, [0, -28], 38)
  ctx.save(); ctx.translate(0, bob)
  // body / mantle
  const bg = ctx.createRadialGradient(-8, -74, 4, 0, -58, 42)
  bg.addColorStop(0, mix(pal.color, '#ffffff', 0.3))
  bg.addColorStop(0.6, pal.color)
  bg.addColorStop(1, shade(pal.color, -0.45))
  ell(ctx, 0, -58, 34, 38, -0.12)
  ctx.fillStyle = bg; ctx.fill()
  ctx.strokeStyle = rgba(pal.deep, 0.8); ctx.lineWidth = 1.5; ctx.stroke()

  // fins
  for (const s of [-1, 1]) {
    ctx.beginPath()
    ctx.moveTo(s * 28, -58)
    ctx.quadraticCurveTo(s * 50, -68, s * 44, -42)
    ctx.quadraticCurveTo(s * 36, -46, s * 27, -44)
    ctx.closePath()
    ctx.fillStyle = rgba(pal.accent, 0.45); ctx.fill()
    ctx.strokeStyle = rgba(pal.accent, 0.6); ctx.stroke()
  }
  // big eyes
  ctx.save(); ctx.shadowColor = '#ffe9a8'; ctx.shadowBlur = 10
  ctx.fillStyle = '#ffe9a8'
  ell(ctx, -10, -64, 8, 6); ctx.fill()
  ell(ctx, 12, -60, 6, 5); ctx.fill()
  ctx.fillStyle = '#0a1318'
  ell(ctx, -9, -64, 3.6, 3.4); ctx.fill()
  ell(ctx, 12.5, -60, 2.8, 2.8); ctx.fill()
  ctx.restore()
  // beak
  poly(ctx, [[0, -50], [7, -44], [-2, -40], [-7, -46]])
  ctx.fillStyle = mix(pal.accent, '#f4d08a', 0.35); ctx.fill()
  // suckers on visible tendril tips
  ctx.fillStyle = rgba(pal.soft, 0.6)
  for (let i = 0; i < 4; i++) { ell(ctx, -14 + i * 8, -18 + i * 2, 1.6, 1.6); ctx.fill() }
  // mantle spots
  ctx.fillStyle = rgba(pal.soft, 0.22)
  for (let i = 0; i < 5; i++) { ell(ctx, -18 + (i % 3) * 15, -76 + Math.floor(i / 3) * 9, 3, 2); ctx.fill() }
  // crown fin
  poly(ctx, [[-2, -94], [4, -112], [11, -93]])
  ctx.fillStyle = rgba(pal.accent, 0.8); ctx.fill()
  ctx.restore()
}

// ─────────── extra lineage features ───────────
function drawExtra(ctx, extra, pal, t) {
  ctx.save()
  switch (extra) {
    case 'avian':
      ctx.globalAlpha = 0.7
      drawWings(ctx, { ...pal, accent: pal.extraAccent || pal.accent }, t, 'avian', 0.8)
      break
    case 'spirit':
      drawOrbs(ctx, { ...pal, accent: pal.extraAccent || '#d8a9ff' }, t, 5)
      ctx.strokeStyle = rgba(pal.extraAccent || '#d8a9ff', 0.5)
      ctx.lineWidth = 1.2
      ctx.beginPath(); ctx.ellipse(0, -54, 40, 30, 0, 0, TAU); ctx.stroke()
      break
    case 'monster':
      drawHorns(ctx, { ...pal, accent: pal.extraAccent || '#ff9a6b' }, 0.94)
      drawSpikes(ctx, { ...pal, accent: pal.extraAccent || '#ff9a6b' }, -60, 4, rgba(pal.extraAccent || '#ff9a6b', 0.8))
      break
    case 'insect':
      ctx.strokeStyle = rgba(pal.extraAccent || '#f3d98a', 0.85); ctx.lineWidth = 1.4
      ctx.beginPath(); ctx.moveTo(18, -82); ctx.quadraticCurveTo(30, -104, 42, -102); ctx.stroke()
      ctx.beginPath(); ctx.moveTo(12, -84); ctx.quadraticCurveTo(18, -108, 30, -112); ctx.stroke()
      ctx.globalAlpha = 0.25
      for (const s of [-1, 1]) {
        ctx.save(); ctx.translate(0, -60); ctx.rotate(s * 0.5)
        ell(ctx, -28, 0, 30, 9, -0.4)
        ctx.fillStyle = rgba(pal.extraAccent || '#f3d98a', 0.5); ctx.fill()
        ctx.restore()
      }
      break
    case 'construct':
      ctx.globalAlpha = 0.65
      drawShards(ctx, { ...pal, accent: pal.extraAccent || '#bfcadd' }, t * 1.2)
      break
    case 'beast':
      ctx.fillStyle = rgba(pal.extraAccent || '#9fd0ff', 0.65)
      poly(ctx, [[20, -84], [25, -98], [32, -82]]); ctx.fill()
      poly(ctx, [[30, -82], [38, -95], [42, -80]]); ctx.fill()
      break
    case 'reptile':
      ctx.fillStyle = rgba(pal.extraAccent || '#74e9c4', 0.7)
      for (let i = 0; i < 4; i++) {
        poly(ctx, [[-20 + i * 12, -66], [-16 + i * 12, -78], [-10 + i * 12, -66]]); ctx.fill()
      }
      break
    case 'kraken':
      ctx.globalAlpha = 0.45
      drawTendrils(ctx, { ...pal, accent: pal.extraAccent || '#8ad8e8', color: pal.extraAccent || '#8ad8e8' }, t, 3, [18, -20], 26)
      break
  }
  ctx.restore()
}

// ─────────── main entry ───────────
export function drawCreature(ctx, o) {
  const {
    silhouette = 'beast', extra = null, x = 0, y = 0, scale = 1, facing = 1,
    t = 1, moving = false, attack = 0, flash = 0, alpha = 1,
    color = '#9fd0ff', accent = '#5aa7ff', deep = '#1b3153', soft = '#ffffff',
    extraAccent = null,
  } = o

  const pal = {
    color: flash > 0 ? mix(color, '#ffffff', flash * 0.85) : color,
    accent: flash > 0 ? mix(accent, '#ffffff', flash * 0.7) : accent,
    deep,
    soft,
    extraAccent: extraAccent || accent,
  }

  ctx.save()
  ctx.globalAlpha *= alpha
  ctx.translate(x, y)
  ctx.scale(facing * scale, scale)

  // ground shadow & aura
  const auraR = 52
  const aura = ctx.createRadialGradient(0, -50, 6, 0, -50, auraR)
  aura.addColorStop(0, rgba(accent, 0.22))
  aura.addColorStop(0.6, rgba(accent, 0.07))
  aura.addColorStop(1, rgba(accent, 0))
  ctx.fillStyle = aura
  ell(ctx, 0, -50, auraR, auraR * 0.9); ctx.fill()

  ctx.fillStyle = 'rgba(0,0,0,.34)'
  ell(ctx, 0, 0, 32, 5.5); ctx.fill()

  const walk = t * 8
  const lunge = attack > 0 ? Math.sin(attack * Math.PI) * 9 : 0
  ctx.translate(lunge, 0)

  ctx.save()
  const fn = { beast: drawBeast, avian: drawAvian, reptile: drawReptile, turtle: drawTurtle,
    insect: drawInsect, construct: drawConstruct, spirit: drawSpirit, monster: drawMonster, kraken: drawKraken }[silhouette] || drawBeast
  fn(ctx, pal, t, moving, attack, walk)
  ctx.restore()

  if (extra && extra !== silhouette) drawExtra(ctx, extra, pal, t)
  ctx.restore()
}

// ─────────── portrait rendering ───────────
export function renderPortrait(canvas, fighter, opts = {}) {
  const {
    size = 96, t = 1.2, ring = true, familyColor = '#d9ad62', showPedestal = true,
    animate = false, pickT = null,
  } = opts
  const dpr = Math.min(window.devicePixelRatio || 1, 2)
  const W = size, H = size
  canvas.width = Math.round(W * dpr)
  canvas.height = Math.round(H * dpr)
  if (!canvas.style.width) canvas.style.width = '100%'
  const ctx = canvas.getContext('2d')
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0)
  ctx.clearRect(0, 0, W, H)

  const c = fighter
  const color = c.color || '#9fd0ff'
  const accent = c.accent || '#5aa7ff'
  const deep = c.deep || '#1b3153'
  const soft = c.soft || '#ffffff'

  // atmosphere
  const bg = ctx.createRadialGradient(W * 0.5, H * 0.46, 2, W * 0.5, H * 0.5, W * 0.62)
  bg.addColorStop(0, rgba(accent, 0.22))
  bg.addColorStop(0.55, rgba(deep, 0.4))
  bg.addColorStop(1, 'rgba(5,8,15,0)')
  ctx.fillStyle = bg
  ctx.fillRect(0, 0, W, H)

  // concentric rings
  if (ring) {
    ctx.save()
    ctx.strokeStyle = rgba(familyColor, 0.22)
    ctx.lineWidth = 1
    ctx.beginPath(); ctx.arc(W / 2, H * 0.48, W * 0.33, 0, TAU); ctx.stroke()
    ctx.setLineDash([2, 5])
    ctx.strokeStyle = rgba(familyColor, 0.28)
    ctx.beginPath(); ctx.arc(W / 2, H * 0.48, W * 0.41, 0, TAU); ctx.stroke()
    ctx.restore()
  }

  // specks
  ctx.save()
  ctx.fillStyle = rgba(accent, 0.4)
  for (let i = 0; i < 7; i++) {
    const a = i * 2.4 + 0.6
    const r = (0.24 + (i % 3) * 0.09) * W
    const px = W / 2 + Math.cos(a) * r
    const py = H * 0.48 + Math.sin(a) * r * 0.8
    ell(ctx, px, py, 0.9, 0.9); ctx.fill()
  }
  ctx.restore()

  if (showPedestal) {
    ctx.save()
    ctx.strokeStyle = rgba(familyColor, 0.35)
    ctx.lineWidth = 1
    ctx.beginPath(); ctx.ellipse(W / 2, H * 0.84, W * 0.3, W * 0.07, 0, 0, TAU); ctx.stroke()
    ctx.beginPath(); ctx.ellipse(W / 2, H * 0.84, W * 0.22, W * 0.048, 0, 0, TAU); ctx.stroke()
    ctx.restore()
  }

  const scale = (H / 128) * (opts.zoom || 1)
  drawCreature(ctx, {
    silhouette: c.silhouette || 'beast',
    extra: c.extra || null,
    x: W / 2,
    y: H * 0.855,
    scale,
    facing: opts.facing || 1,
    t: pickT != null ? pickT : (animate ? t : 1.2),
    moving: false,
    color, accent, deep, soft,
    extraAccent: c.extraAccent || null,
  })

  // vignette
  const vg = ctx.createRadialGradient(W / 2, H / 2, W * 0.32, W / 2, H / 2, W * 0.72)
  vg.addColorStop(0, 'rgba(0,0,0,0)')
  vg.addColorStop(1, 'rgba(3,5,10,.45)')
  ctx.fillStyle = vg
  ctx.fillRect(0, 0, W, H)
}

export function makePortrait(fighter, size = 64, opts = {}) {
  const canvas = document.createElement('canvas')
  canvas.className = opts.className || 'portrait-canvas'
  renderPortrait(canvas, fighter, { size, ...opts })
  return canvas
}

@font-face {
  font-family: 'Cinzel';
  src: url('assets/fonts/cinzel.woff2') format('woff2');
  font-weight: 400 900;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: 'Manrope';
  src: url('assets/fonts/manrope.woff2') format('woff2');
  font-weight: 200 800;
  font-style: normal;
  font-display: swap;
}

:root {
  --bg: #06080f;
  --bg-2: #0a0e19;
  --ink: #e9e4d6;
  --muted: #8b90a3;
  --dim: #5e6478;
  --gold: #d9ad62;
  --gold-bright: #f6e6b4;
  --gold-dim: #8c6a34;
  --line: rgba(217, 173, 98, 0.18);
  --line-soft: rgba(180, 195, 230, 0.1);
  --panel: rgba(12, 17, 28, 0.82);
  --panel-2: rgba(16, 22, 36, 0.9);
  --ally: #81d7ff;
  --enemy: #ff8b78;
  --violet: #c79bff;
  --green: #7fe3ac;
  --font-display: 'Cinzel', Georgia, serif;
  --font-ui: 'Manrope', system-ui, sans-serif;
  --ease: cubic-bezier(0.22, 1, 0.36, 1);
}

* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
html { background: var(--bg); }
body {
  min-height: 100vh;
  color: var(--ink);
  font-family: var(--font-ui);
  font-size: 14px;
  overflow: hidden;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}
button { font-family: inherit; color: inherit; cursor: pointer; }
button:focus-visible { outline: 1px solid var(--gold); outline-offset: 3px; }
h1, h2, h3, p { margin: 0; }
.hidden { display: none !important; }

/* ───────────────────────── backdrop ───────────────────────── */
.backdrop { position: fixed; inset: 0; z-index: 0; overflow: hidden; background: var(--bg); }
.backdrop::before {
  content: ''; position: absolute; inset: 0;
  background:
    radial-gradient(ellipse at 50% -20%, rgba(60, 78, 130, 0.28), transparent 60%),
    radial-gradient(ellipse at 85% 105%, rgba(120, 65, 120, 0.14), transparent 55%),
    linear-gradient(180deg, #080b14, #05070d 60%, #070a11);
}
.nebula { position: absolute; border-radius: 50%; filter: blur(70px); opacity: 0.5; will-change: transform; }
.nebula-a { width: 55vw; height: 55vw; left: -18vw; top: -20vw; background: radial-gradient(circle, rgba(50, 90, 150, 0.4), transparent 65%); animation: drift 38s ease-in-out infinite alternate; }
.nebula-b { width: 45vw; height: 45vw; right: -15vw; top: 10vh; background: radial-gradient(circle, rgba(150, 90, 60, 0.22), transparent 65%); animation: drift 48s ease-in-out infinite alternate-reverse; }
.nebula-c { width: 50vw; height: 40vw; left: 28vw; bottom: -25vw; background: radial-gradient(circle, rgba(100, 55, 140, 0.18), transparent 65%); animation: drift 55s ease-in-out infinite alternate; }
@keyframes drift { from { transform: translate3d(-2%, -1%, 0) scale(1); } to { transform: translate3d(3%, 2%, 0) scale(1.08); } }
.stars {
  position: absolute; inset: 0; opacity: 0.55;
  background-image:
    radial-gradient(1px 1px at 12% 22%, rgba(255,255,255,.7), transparent),
    radial-gradient(1px 1px at 28% 68%, rgba(220,235,255,.55), transparent),
    radial-gradient(1.4px 1.4px at 47% 12%, rgba(255,255,255,.45), transparent),
    radial-gradient(1px 1px at 63% 42%, rgba(255,255,255,.6), transparent),
    radial-gradient(1px 1px at 78% 74%, rgba(255,240,210,.55), transparent),
    radial-gradient(1.4px 1.4px at 88% 18%, rgba(255,255,255,.5), transparent),
    radial-gradient(1px 1px at 38% 88%, rgba(220,235,255,.4), transparent),
    radial-gradient(1px 1px at 7% 82%, rgba(255,255,255,.35), transparent);
  background-size: 900px 700px;
  animation: twinkle 9s ease-in-out infinite alternate;
}
@keyframes twinkle { from { opacity: .32; } to { opacity: .62; } }
.grain {
  position: absolute; inset: 0; opacity: 0.035; pointer-events: none;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.85' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
}

/* ───────────────────────── shell ───────────────────────── */
#app { position: relative; z-index: 2; height: 100vh; display: flex; flex-direction: column; }
.topbar {
  height: 62px; flex: 0 0 auto;
  display: flex; align-items: center; gap: 20px;
  padding: 0 22px;
  border-bottom: 1px solid rgba(217, 173, 98, 0.14);
  background: linear-gradient(180deg, rgba(8, 11, 19, 0.94), rgba(7, 10, 17, 0.72));
  backdrop-filter: blur(14px);
  position: relative;
}
.topbar::after {
  content: ''; position: absolute; left: 0; right: 0; bottom: -1px; height: 1px;
  background: linear-gradient(90deg, transparent, rgba(217, 173, 98, 0.38), transparent);
}
.brand { display: flex; align-items: center; gap: 11px; min-width: 220px; }
.brand-mark { width: 38px; height: 38px; filter: drop-shadow(0 0 8px rgba(217, 173, 98, 0.3)); }
.brand-text { display: flex; flex-direction: column; line-height: 1; }
.brand-name {
  font-family: var(--font-display); font-weight: 700; font-size: 23px; letter-spacing: 0.2em;
  background: linear-gradient(180deg, #f8ecc8, #c99a4d 65%, #8c6428);
  -webkit-background-clip: text; background-clip: text; color: transparent;
}
.brand-sub { font-size: 8px; letter-spacing: 0.32em; text-transform: uppercase; color: var(--muted); margin-top: 5px; padding-left: 2px; }

.runline { flex: 1; display: flex; align-items: center; justify-content: center; gap: 16px; min-width: 0; }
.round-pips { display: flex; gap: 5px; align-items: center; }
.round-pip {
  width: 8px; height: 8px; transform: rotate(45deg);
  border: 1px solid rgba(217, 173, 98, 0.35); background: transparent;
  transition: all .3s var(--ease);
}
.round-pip.done { background: var(--gold); border-color: var(--gold); box-shadow: 0 0 8px rgba(217,173,98,.55); }
.round-pip.current { border-color: var(--gold-bright); box-shadow: 0 0 0 3px rgba(217,173,98,.12), 0 0 10px rgba(217,173,98,.3); }
.round-pip.failed { background: rgba(255, 110, 90, .7); border-color: #ff6e5a; }
.run-copy { display: flex; flex-direction: column; line-height: 1; min-width: 0; }
.run-label { font-size: 8px; letter-spacing: .34em; color: var(--gold); text-transform: uppercase; margin-bottom: 5px; }
.run-title { font-family: var(--font-display); font-size: 13px; letter-spacing: .17em; color: #d8d1c1; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

.top-actions { display: flex; align-items: center; gap: 8px; min-width: 220px; justify-content: flex-end; }
.stat-pill {
  height: 34px; display: flex; align-items: center; gap: 7px; padding: 0 12px;
  border: 1px solid var(--line); background: rgba(217, 173, 98, 0.04);
  font-size: 13px; font-weight: 700; color: var(--gold-bright);
  clip-path: polygon(7px 0, 100% 0, 100% calc(100% - 7px), calc(100% - 7px) 100%, 0 100%, 0 7px);
}
.ember-pill svg { width: 14px; height: 14px; color: #ff8d5d; }
.aether-pill { color: var(--ink); gap: 6px; }
.aether-word { font-size: 7px; letter-spacing: .22em; color: var(--muted); font-weight: 600; }
.aether-orb {
  width: 11px; height: 11px; border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, #f9ecc4, #d9ad62 45%, #7e5a24);
  box-shadow: 0 0 10px rgba(217, 173, 98, 0.7);
}
.icon-btn {
  width: 34px; height: 34px; display: grid; place-items: center;
  border: 1px solid var(--line-soft); background: rgba(255,255,255,0.02); color: #b9bece;
  transition: all .2s var(--ease);
}
.icon-btn:hover { border-color: var(--line); color: var(--gold-bright); background: rgba(217,173,98,.06); }
.icon-btn svg { width: 17px; height: 17px; }
.sound-off { display: none; }
body.muted .sound-off { display: block; }
body.muted .sound-on { display: none; }

#main { flex: 1; min-height: 0; position: relative; }
.view { height: 100%; }

/* ───────────────────────── prep ───────────────────────── */
.prep-view { display: flex; flex-direction: column; padding: 16px 22px 16px; gap: 13px; }
.prep-head { display: flex; align-items: flex-end; justify-content: space-between; gap: 24px; flex: 0 0 auto; }
.prep-heading { min-width: 0; }
.eyebrow {
  display: flex; align-items: center; gap: 10px; font-size: 8px; letter-spacing: .34em;
  text-transform: uppercase; color: var(--gold); font-weight: 700;
}
.rule { width: 22px; height: 1px; background: linear-gradient(90deg, transparent, var(--gold-dim)); }
.eyebrow .rule:last-child { background: linear-gradient(90deg, var(--gold-dim), transparent); }
.prep-heading h1 {
  font-family: var(--font-display); font-size: clamp(26px, 2.6vw, 38px); letter-spacing: .1em;
  font-weight: 700; line-height: 1.08; margin: 7px 0 7px;
  background: linear-gradient(180deg, #faf1d5, #d6ad6b 60%, #a67c3e);
  -webkit-background-clip: text; background-clip: text; color: transparent;
  filter: drop-shadow(0 2px 10px rgba(0,0,0,.5));
}
.prep-heading p { color: #9499aa; font-size: 11.5px; max-width: 660px; line-height: 1.55; }
.prep-heading p strong { color: #d9c9a4; font-weight: 600; }
.step-track { display: flex; gap: 6px; padding-bottom: 4px; }
.step {
  min-width: 92px; padding: 8px 10px 7px; border: 1px solid var(--line-soft);
  background: rgba(12,17,28,.5); display: flex; flex-direction: column; gap: 3px;
  transition: all .3s var(--ease);
}
.step span { font-family: var(--font-display); font-size: 9px; color: var(--dim); letter-spacing: .1em; }
.step em { font-style: normal; font-size: 8.5px; color: #767d90; letter-spacing: .04em; white-space: nowrap; }
.step.active { border-color: rgba(217,173,98,.4); background: rgba(217,173,98,.06); }
.step.active span { color: var(--gold); }
.step.active em { color: #d9d2c2; }

.prep-grid { flex: 1; min-height: 0; display: grid; grid-template-columns: 336px minmax(0, 1fr) 366px; gap: 13px; }
.panel {
  position: relative; min-height: 0; display: flex; flex-direction: column;
  border: 1px solid rgba(200, 180, 140, .13);
  background:
    linear-gradient(160deg, rgba(23, 30, 47, 0.72), rgba(9, 13, 22, 0.9) 45%, rgba(7, 10, 17, 0.94));
  box-shadow: 0 18px 50px rgba(0, 0, 0, 0.35), inset 0 1px 0 rgba(255,255,255,.03);
}
.panel::before, .panel::after {
  content: ''; position: absolute; width: 14px; height: 14px; pointer-events: none;
  border-color: rgba(217,173,98,.5); border-style: solid; z-index: 2;
}
.panel::before { top: -1px; left: -1px; border-width: 1px 0 0 1px; }
.panel::after { bottom: -1px; right: -1px; border-width: 0 1px 1px 0; }
.panel-head {
  flex: 0 0 auto; display: flex; align-items: flex-start; justify-content: space-between; gap: 10px;
  padding: 13px 15px 11px; border-bottom: 1px solid rgba(200,180,140,.09);
  background: linear-gradient(180deg, rgba(255,255,255,.025), transparent);
}
.panel-head h2 { font-family: var(--font-display); font-size: 12px; letter-spacing: .19em; color: #ddd3bd; font-weight: 700; }
.panel-sub { display: block; font-size: 9px; color: var(--dim); margin-top: 4px; letter-spacing: .04em; }
.pick-hint { font-size: 8px; letter-spacing: .12em; color: var(--gold); text-transform: uppercase; padding-top: 2px; text-align: right; max-width: 110px; line-height: 1.5; }
.cost-tag { font-size: 8px; letter-spacing: .14em; color: var(--gold-bright); border: 1px solid rgba(217,173,98,.3); padding: 4px 7px; white-space: nowrap; background: rgba(217,173,98,.06); }
.lane-count { font-family: var(--font-display); font-size: 11px; color: var(--gold); letter-spacing: .1em; }
.tiny { font-size: 9px; color: var(--dim); line-height: 1.5; }

/* lineage slots */
.lineage-slots { display: flex; gap: 6px; padding: 9px 12px 0; }
.lineage-slot {
  flex: 1; min-width: 0; height: 38px; border: 1px dashed rgba(180,195,230,.16);
  display: flex; align-items: center; gap: 7px; padding: 0 8px; background: rgba(255,255,255,.012);
  transition: all .25s var(--ease); position: relative; overflow: hidden;
}
.lineage-slot.filled { border-style: solid; border-color: rgba(217,173,98,.35); background: rgba(217,173,98,.05); }
.lineage-slot .slot-mark {
  width: 16px; height: 16px; flex: 0 0 auto; display: grid; place-items: center;
  border-radius: 50%; font-family: var(--font-display); font-size: 8px; font-weight: 700;
  border: 1px solid rgba(180,195,230,.25); color: var(--muted);
}
.lineage-slot.prime .slot-mark { border-color: rgba(217,173,98,.5); color: var(--gold); }
.lineage-slot.seed .slot-mark { border-color: rgba(127,227,172,.45); color: var(--green); }
.lineage-slot .slot-text { min-width: 0; flex: 1; }
.lineage-slot .slot-label { display: block; font-size: 7px; letter-spacing: .18em; color: var(--dim); text-transform: uppercase; }
.lineage-slot .slot-name { display: block; font-size: 10px; font-weight: 700; color: #d8d2c3; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; margin-top: 2px; }
.lineage-slot.empty .slot-name { color: #5e6478; font-weight: 500; }
.lineage-slot .slot-x {
  width: 18px; height: 18px; border: 0; background: transparent; color: var(--dim); font-size: 13px;
  display: grid; place-items: center; padding: 0; flex: 0 0 auto;
}
.lineage-slot .slot-x:hover { color: #ff9f8f; }
.lineage-slot .slot-swatch { width: 3px; height: 22px; flex: 0 0 auto; border-radius: 2px; }

/* essence grid */
.essence-panel { overflow: hidden; }
.essence-grid {
  flex: 1; min-height: 0; overflow-y: auto; padding: 9px 12px 4px;
  display: grid; grid-template-columns: 1fr 1fr; gap: 6px; align-content: start;
  scrollbar-width: thin; scrollbar-color: rgba(217,173,98,.25) transparent;
}
.essence-grid::-webkit-scrollbar { width: 4px; }
.essence-grid::-webkit-scrollbar-thumb { background: rgba(217,173,98,.25); }
.essence-card {
  position: relative; border: 1px solid rgba(180,195,230,.1); background: rgba(255,255,255,.018);
  min-height: 56px; display: flex; align-items: center; gap: 8px; padding: 6px 7px; text-align: left;
  transition: all .22s var(--ease); overflow: hidden;
}
.essence-card::after {
  content: ''; position: absolute; inset: 0; pointer-events: none;
  background: linear-gradient(110deg, transparent 30%, rgba(255,255,255,.06) 45%, transparent 60%);
  transform: translateX(-120%); transition: transform .5s var(--ease);
}
.essence-card:hover { border-color: rgba(217,173,98,.35); background: rgba(217,173,98,.05); transform: translateY(-1px); }
.essence-card:hover::after { transform: translateX(120%); }
.essence-card.selected-prime { border-color: rgba(217,173,98,.65); background: rgba(217,173,98,.09); box-shadow: 0 0 0 1px rgba(217,173,98,.15), 0 6px 20px rgba(0,0,0,.3); }
.essence-card.selected-seed { border-color: rgba(127,227,172,.45); background: rgba(127,227,172,.055); }
.essence-card .e-art {
  width: 42px; height: 42px; flex: 0 0 auto; border-radius: 50%; overflow: hidden;
  border: 1px solid rgba(255,255,255,.08); background: rgba(0,0,0,.25);
  position: relative;
}
.essence-card .e-art canvas { width: 100%; height: 100%; display: block; }
.essence-card .e-copy { min-width: 0; flex: 1; }
.essence-card .e-name { display: block; font-size: 10px; font-weight: 700; color: #ddd6c7; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.essence-card .e-meta { display: flex; align-items: center; gap: 5px; margin-top: 3px; font-size: 7.5px; letter-spacing: .08em; color: var(--dim); text-transform: uppercase; white-space: nowrap; }
.essence-card .family-dot { width: 4px; height: 4px; border-radius: 50%; flex: 0 0 auto; }
.essence-card .e-role { color: #7f869a; }
.essence-card .pick-badge {
  position: absolute; top: 4px; right: 4px; width: 15px; height: 15px; display: grid; place-items: center;
  font-family: var(--font-display); font-size: 8px; font-weight: 700; color: #0b0e15;
  background: var(--gold); clip-path: polygon(50% 0, 100% 50%, 50% 100%, 0 50%);
}
.essence-card.selected-seed .pick-badge { background: var(--green); }
.vault-foot {
  flex: 0 0 auto; display: flex; align-items: center; gap: 6px; padding: 9px 14px 11px;
  border-top: 1px solid rgba(200,180,140,.07); font-size: 8px; color: var(--dim);
}
.vault-foot span:nth-child(2) { margin-right: 6px; }
.legend-dot { width: 5px; height: 5px; border-radius: 50%; }
.legend-dot.prime { background: var(--gold); }
.legend-dot.seed { background: var(--green); }

/* forge */
.forge-panel { overflow: hidden; }
.forge-body {
  flex: 1; min-height: 0; overflow-y: auto; padding: 12px 16px 14px; display: flex; flex-direction: column;
  scrollbar-width: thin; scrollbar-color: rgba(217,173,98,.25) transparent;
}
.forge-body::-webkit-scrollbar { width: 4px; }
.forge-body::-webkit-scrollbar-thumb { background: rgba(217,173,98,.25); }
.forge-empty { flex: 1; display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; gap: 14px; padding: 20px; }
.forge-sigil { width: 130px; height: 130px; position: relative; opacity: .7; }
.forge-sigil .ring { position: absolute; inset: 0; border: 1px solid rgba(217,173,98,.25); border-radius: 50%; }
.forge-sigil .ring:nth-child(2) { inset: 13px; border-style: dashed; border-color: rgba(180,195,230,.18); animation: spin 26s linear infinite; }
.forge-sigil .ring:nth-child(3) { inset: 30px; border-color: rgba(217,173,98,.3); }
.forge-sigil .core {
  position: absolute; inset: 47px; border-radius: 50%;
  background: radial-gradient(circle at 38% 32%, rgba(246,230,180,.9), rgba(217,173,98,.4) 40%, transparent 70%);
  box-shadow: 0 0 34px rgba(217,173,98,.25);
  animation: pulse 3s ease-in-out infinite;
}
@keyframes spin { to { transform: rotate(360deg); } }
@keyframes pulse { 0%,100% { transform: scale(1); opacity: .8; } 50% { transform: scale(1.16); opacity: 1; } }
.forge-empty h3 { font-family: var(--font-display); font-size: 17px; letter-spacing: .15em; color: #cfc4aa; font-weight: 600; }
.forge-empty p { font-size: 10px; color: var(--dim); max-width: 280px; line-height: 1.6; }
.forge-empty .lineage-pair { display: flex; gap: 8px; align-items: center; color: var(--gold); font-size: 11px; letter-spacing: .12em; }
.forge-empty .ghost-slot {
  width: 56px; height: 62px; border: 1px dashed rgba(217,173,98,.28); display: grid; place-items: center;
  font-family: var(--font-display); font-size: 16px; color: rgba(217,173,98,.5); background: rgba(217,173,98,.03);
}

.forge-result { display: flex; flex-direction: column; gap: 9px; flex: 1; }
.forge-hero { display: flex; gap: 14px; align-items: center; min-height: 148px; }
.forge-portrait {
  width: 148px; height: 148px; flex: 0 0 auto; position: relative;
  border-radius: 50%; overflow: hidden;
  border: 1px solid rgba(217,173,98,.25);
  background: radial-gradient(circle at 50% 40%, rgba(30,40,62,.8), rgba(6,9,16,.9));
  box-shadow: inset 0 0 30px rgba(0,0,0,.6), 0 0 32px rgba(217,173,98,.08);
}
.forge-portrait::before {
  content: ''; position: absolute; inset: 6px; border-radius: 50%;
  border: 1px dashed rgba(217,173,98,.2); animation: spin 40s linear infinite; pointer-events: none;
}
.forge-portrait::after {
  content: ''; position: absolute; inset: 0; border-radius: 50%;
  box-shadow: inset 0 0 40px rgba(0,0,0,.55); pointer-events: none;
}
.forge-portrait canvas { width: 100%; height: 100%; display: block; }
.forge-id { min-width: 0; flex: 1; }
.lineage-mini { display: flex; align-items: center; gap: 5px; font-size: 8px; letter-spacing: .12em; color: var(--dim); text-transform: uppercase; margin-bottom: 5px; flex-wrap: wrap; }
.lineage-mini b { color: var(--gold); font-weight: 700; }
.lineage-mini i { font-style: normal; color: #4a5062; }
.lineage-mini .mut { color: var(--violet); }
.forge-name { font-family: var(--font-display); font-size: clamp(21px, 2vw, 30px); line-height: 1.02; letter-spacing: .02em; font-weight: 700; color: #f2ead9; }
.forge-epithet { font-family: var(--font-display); font-size: 10px; letter-spacing: .14em; color: var(--gold); margin-top: 4px; font-style: italic; }
.forge-badges { display: flex; gap: 4px; flex-wrap: wrap; margin-top: 8px; }
.chip {
  font-size: 7px; letter-spacing: .12em; text-transform: uppercase; padding: 3px 6px;
  border: 1px solid rgba(180,195,230,.14); color: #9ba2b5; background: rgba(255,255,255,.02);
}
.chip.gold { color: var(--gold); border-color: rgba(217,173,98,.28); background: rgba(217,173,98,.05); }
.chip.violet { color: var(--violet); border-color: rgba(199,155,255,.25); background: rgba(199,155,255,.05); }
.chip.green { color: var(--green); border-color: rgba(127,227,172,.25); background: rgba(127,227,172,.05); }
.forge-power { display: flex; align-items: baseline; gap: 5px; margin-top: 7px; }
.forge-power span { font-size: 7px; letter-spacing: .2em; color: var(--dim); }
.forge-power b { font-family: var(--font-display); font-size: 18px; color: var(--gold-bright); font-weight: 700; }
.forge-power em { font-size: 8px; color: var(--green); font-style: normal; letter-spacing: .08em; }

.stat-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 5px; }
.stat-box {
  border: 1px solid rgba(180,195,230,.09); background: rgba(255,255,255,.018);
  padding: 6px 7px 5px; position: relative; overflow: hidden;
}
.stat-box span { display: block; font-size: 6.5px; letter-spacing: .18em; color: var(--dim); text-transform: uppercase; }
.stat-box b { display: block; font-family: var(--font-display); font-size: 15px; color: #e3dbc9; margin-top: 2px; font-weight: 600; }
.stat-box i { position: absolute; left: 0; bottom: 0; height: 2px; background: linear-gradient(90deg, var(--gold), transparent); opacity: .5; }

.trait-list { display: flex; flex-direction: column; gap: 4px; }
.trait {
  display: flex; align-items: flex-start; gap: 8px; padding: 6px 8px;
  border: 1px solid rgba(180,195,230,.07); background: rgba(255,255,255,.014);
}
.trait-icon {
  width: 22px; height: 22px; flex: 0 0 auto; display: grid; place-items: center;
  border-radius: 50%; font-size: 9px; border: 1px solid rgba(217,173,98,.28); color: var(--gold);
  background: rgba(217,173,98,.06); font-family: var(--font-display);
}
.trait.passive .trait-icon { border-color: rgba(127,227,172,.28); color: var(--green); background: rgba(127,227,172,.06); }
.trait.mutation .trait-icon { border-color: rgba(199,155,255,.3); color: var(--violet); background: rgba(199,155,255,.06); }
.trait-copy { min-width: 0; }
.trait-copy b { display: block; font-size: 9px; color: #d4cdbe; letter-spacing: .03em; }
.trait-copy b em { font-style: normal; font-size: 6.5px; letter-spacing: .13em; color: var(--dim); text-transform: uppercase; margin-left: 4px; }
.trait-copy p { font-size: 8px; line-height: 1.45; color: #7d8498; margin-top: 1px; }
.mutation-row { display: flex; gap: 4px; flex-wrap: wrap; }
.mutation-chip { font-size: 7.5px; color: var(--violet); border: 1px solid rgba(199,155,255,.22); background: rgba(199,155,255,.05); padding: 3px 6px; }
.resonance-note {
  display: flex; align-items: center; gap: 7px; padding: 6px 8px;
  border-left: 2px solid var(--res-color, var(--green));
  background: linear-gradient(90deg, rgba(127,227,172,.06), transparent);
  font-size: 8px; color: #8d94a7; line-height: 1.4;
}
.resonance-note b { color: #d4cdbe; font-weight: 600; }
.resonance-note .res-glyph { color: var(--res-color, var(--green)); font-size: 10px; }
.matchup {
  display: flex; align-items: center; justify-content: space-between; gap: 8px;
  border: 1px solid rgba(180,195,230,.1); padding: 5px 8px; background: rgba(0,0,0,.16);
}
.matchup span { font-size: 7px; letter-spacing: .16em; color: var(--dim); text-transform: uppercase; }
.matchup b { font-size: 8.5px; letter-spacing: .08em; color: var(--green); }
.matchup b.risky { color: #ff9c8a; }
.matchup b.even { color: var(--gold); }
.fuse-btn {
  margin-top: auto; height: 42px; flex: 0 0 auto; position: relative; overflow: hidden;
  border: 1px solid rgba(217,173,98,.58); color: #100e09; font-weight: 800;
  background: linear-gradient(180deg, #f3dfad, #d7ac63 55%, #b0833e);
  font-size: 10px; letter-spacing: .17em; text-transform: uppercase;
  clip-path: polygon(9px 0, 100% 0, 100% calc(100% - 9px), calc(100% - 9px) 100%, 0 100%, 0 9px);
  transition: all .2s var(--ease);
}
.fuse-btn:hover:not(:disabled) { filter: brightness(1.12); box-shadow: 0 0 26px rgba(217,173,98,.3); }
.fuse-btn:disabled { filter: grayscale(.8) brightness(.55); cursor: not-allowed; }
.fuse-btn small { display: block; font-size: 6.5px; letter-spacing: .14em; margin-top: 1px; opacity: .62; font-weight: 700; }
.fuse-btn .sheen { position: absolute; inset: 0; background: linear-gradient(105deg, transparent 35%, rgba(255,255,255,.5) 48%, transparent 60%); transform: translateX(-110%); transition: transform .7s var(--ease); }
.fuse-btn:hover:not(:disabled) .sheen { transform: translateX(110%); }

/* deploy */
.deploy-panel { overflow: hidden; }
.lane-list { flex: 1; min-height: 0; overflow-y: auto; padding: 8px 10px 2px; display: flex; flex-direction: column; gap: 5px; scrollbar-width: thin; scrollbar-color: rgba(217,173,98,.25) transparent; }
.lane-list::-webkit-scrollbar { width: 4px; }
.lane-list::-webkit-scrollbar-thumb { background: rgba(217,173,98,.25); }
.lane-card {
  position: relative; width: 100%; text-align: left; flex: 1 0 auto; min-height: 82px;
  display: grid; grid-template-columns: 62px minmax(0,1fr) 20px minmax(0,1fr); align-items: center; gap: 4px;
  border: 1px solid rgba(180,195,230,.09); padding: 7px 6px 7px 7px;
  background: linear-gradient(90deg, rgba(255,255,255,.022), rgba(255,255,255,.006));
  transition: all .22s var(--ease); overflow: hidden;
}
.lane-card:hover { border-color: rgba(217,173,98,.3); background: rgba(217,173,98,.035); }
.lane-card.selected { border-color: rgba(217,173,98,.55); background: linear-gradient(90deg, rgba(217,173,98,.09), rgba(217,173,98,.02)); box-shadow: inset 3px 0 0 var(--gold); }
.lane-ident { display: flex; flex-direction: column; gap: 3px; min-width: 0; }
.lane-roman { font-family: var(--font-display); font-size: 15px; color: var(--gold); line-height: 1; letter-spacing: .04em; }
.terrain-name { font-size: 6.5px; letter-spacing: .11em; color: #9aa1b2; text-transform: uppercase; line-height: 1.25; }
.terrain-bonus { font-size: 6px; letter-spacing: .04em; color: var(--terr-color, var(--green)); }
.unit-chip { display: flex; align-items: center; gap: 5px; min-width: 0; position: relative; }
.unit-chip .u-art { width: 32px; height: 32px; flex: 0 0 auto; border-radius: 50%; overflow: hidden; border: 1px solid rgba(255,255,255,.08); background: rgba(0,0,0,.25); }
.unit-chip .u-art canvas { width: 100%; height: 100%; display: block; }
.unit-chip .u-copy { min-width: 0; }
.unit-chip .u-name { display: block; font-size: 8.5px; font-weight: 700; color: #cfc8b8; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.unit-chip .u-stat { display: block; font-size: 6.5px; color: var(--dim); letter-spacing: .03em; margin-top: 2px; white-space: nowrap; }
.unit-chip .u-stat b { color: #a9afc0; font-weight: 600; }
.unit-chip.enemy .u-name { color: #d5b9b2; }
.unit-chip.enemy .u-stat b { color: #c4a09a; }
.unit-chip .res-mark {
  position: absolute; right: 0; top: -1px; width: 10px; height: 10px; display: grid; place-items: center;
  font-size: 7px; color: var(--terr-color, var(--green)); text-shadow: 0 0 6px currentColor;
}
.unit-chip.empty .u-art { border-style: dashed; border-color: rgba(180,195,230,.18); display: grid; place-items: center; color: #4c5365; font-family: var(--font-display); font-size: 13px; }
.unit-chip.empty .u-name { color: #5e6478; font-weight: 500; }
.unit-chip.empty .u-stat { color: #4d5466; }
.vs-mark { font-family: var(--font-display); font-size: 7px; color: #4a5062; text-align: center; letter-spacing: .05em; }
.lane-card .lane-status {
  position: absolute; top: 4px; right: 4px; font-size: 6px; letter-spacing: .12em;
  color: var(--gold); opacity: 0; transition: opacity .2s;
}
.lane-card.selected .lane-status { opacity: 1; }
.lane-card.occupied .lane-status { color: var(--muted); }
.battle-cta { flex: 0 0 auto; padding: 10px 12px 12px; border-top: 1px solid rgba(200,180,140,.08); }
.primary-btn {
  position: relative; width: 100%; height: 46px; border: 1px solid rgba(217,173,98,.55);
  background: linear-gradient(180deg, #efdaa6, #d4a75b 56%, #aa7c38);
  color: #0e0c08; font-size: 10.5px; font-weight: 800; letter-spacing: .17em; text-transform: uppercase;
  display: flex; align-items: center; justify-content: center; gap: 8px; overflow: hidden;
  clip-path: polygon(9px 0, 100% 0, 100% calc(100% - 9px), calc(100% - 9px) 100%, 0 100%, 0 9px);
  transition: all .2s var(--ease);
}
.primary-btn svg { width: 16px; height: 16px; }
.primary-btn:hover:not(:disabled) { filter: brightness(1.1); box-shadow: 0 0 28px rgba(217,173,98,.3); }
.primary-btn:disabled { filter: grayscale(.85) brightness(.45); cursor: not-allowed; }
.btn-sheen { position: absolute; inset: 0; background: linear-gradient(105deg, transparent 35%, rgba(255,255,255,.45) 48%, transparent 60%); transform: translateX(-110%); transition: transform .7s var(--ease); }
.primary-btn:hover:not(:disabled) .btn-sheen { transform: translateX(110%); }
.btn-label { position: relative; }
#deployHint { text-align: center; margin-top: 6px; font-size: 8px; color: var(--dim); }
#deployHint.ready { color: var(--green); }

/* ───────────────────────── battle ───────────────────────── */
.battle-view { display: flex; flex-direction: column; padding: 11px 18px 12px; gap: 8px; }
.battle-head { flex: 0 0 auto; display: grid; grid-template-columns: 1fr auto 1fr; align-items: center; gap: 12px; }
.score-side { display: flex; align-items: center; gap: 12px; }
.score-side.enemy { justify-content: flex-end; }
.score-label { font-size: 7.5px; letter-spacing: .2em; color: var(--muted); text-transform: uppercase; white-space: nowrap; }
.score-side.ally .score-label { color: #9ed8f5; }
.score-side.enemy .score-label { color: #e1a39a; }
.score-pips { display: flex; gap: 5px; }
.score-pips .pip {
  width: 24px; height: 7px; transform: skewX(-24deg);
  border: 1px solid rgba(180,195,230,.16); background: rgba(255,255,255,.02); transition: all .3s var(--ease);
}
.score-side.ally .score-pips .pip.won { background: linear-gradient(90deg, #6ecbf5, #c6f1ff); border-color: #a8e5ff; box-shadow: 0 0 12px rgba(129,215,255,.5); }
.score-side.enemy .score-pips .pip.won { background: linear-gradient(90deg, #ff7c66, #ffc2ae); border-color: #ffab97; box-shadow: 0 0 12px rgba(255,123,100,.5); }
.score-pips .pip.contested { border-color: rgba(217,173,98,.45); }
.battle-center { text-align: center; min-width: 200px; }
.phase-line { font-family: var(--font-display); font-size: 12px; letter-spacing: .2em; color: var(--gold-bright); text-transform: uppercase; white-space: nowrap; }
.battle-meta { display: flex; align-items: center; justify-content: center; gap: 6px; margin-top: 4px; font-size: 7.5px; letter-spacing: .12em; color: var(--dim); white-space: nowrap; }
.timer { font-family: var(--font-display); font-size: 11px; color: #d9d2c2; letter-spacing: .08em; }
.dot-sep { color: #3f4555; }
.speed-btn {
  margin-left: 2px; border: 1px solid var(--line-soft); background: transparent; color: var(--muted);
  font-size: 7.5px; padding: 1px 5px; font-weight: 700; letter-spacing: .06em;
}
.speed-btn:hover { color: var(--gold); border-color: var(--line); }

.arena { flex: 1; min-height: 0; display: flex; flex-direction: column; gap: 5px; }
.lane {
  position: relative; flex: 1; min-height: 0; border: 1px solid rgba(180,195,230,.08);
  overflow: hidden; background: #080c15; isolation: isolate;
  transition: border-color .2s, box-shadow .2s;
}
.lane::after {
  content: ''; position: absolute; inset: 0; pointer-events: none;
  background: linear-gradient(90deg, rgba(6,9,16,.72) 0, rgba(6,9,16,.12) 16%, transparent 33%, transparent 67%, rgba(6,9,16,.12) 84%, rgba(6,9,16,.72) 100%);
}
.lane canvas.lane-canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }
.lane .lane-hud {
  position: absolute; top: 0; bottom: 0; width: 196px; z-index: 3;
  display: flex; flex-direction: column; justify-content: center; gap: 3px; padding: 7px 12px;
  pointer-events: none;
}
.lane .lane-hud.ally { left: 0; background: linear-gradient(90deg, rgba(7,11,19,.94), rgba(7,11,19,.55) 62%, transparent); }
.lane .lane-hud.enemy { right: 0; background: linear-gradient(270deg, rgba(7,11,19,.94), rgba(7,11,19,.55) 62%, transparent); align-items: flex-end; text-align: right; }
.lane-hud .hud-top { display: flex; align-items: center; gap: 7px; width: 100%; }
.lane-hud.enemy .hud-top { flex-direction: row-reverse; }
.hud-portrait {
  width: 34px; height: 34px; flex: 0 0 auto; border-radius: 50%; overflow: hidden;
  border: 1px solid rgba(255,255,255,.14); background: rgba(0,0,0,.3);
  box-shadow: 0 0 12px rgba(0,0,0,.5);
}
.hud-portrait canvas { width: 100%; height: 100%; display: block; }
.lane-hud.ally .hud-portrait { border-color: rgba(129,215,255,.4); }
.lane-hud.enemy .hud-portrait { border-color: rgba(255,139,120,.4); }
.hud-id { min-width: 0; flex: 1; }
.lane-hud.enemy .hud-id { text-align: right; }
.hud-name { display: flex; align-items: center; gap: 4px; font-size: 9px; font-weight: 700; color: #d8d1c1; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.lane-hud.enemy .hud-name { justify-content: flex-end; color: #d9bdb7; }
.hud-family { display: block; font-size: 6px; letter-spacing: .14em; color: var(--dim); text-transform: uppercase; margin-top: 1px; }
.hud-bars { width: 100%; margin-top: 4px; }
.hp-track { height: 7px; background: rgba(255,255,255,.07); position: relative; overflow: hidden; border: 1px solid rgba(255,255,255,.06); }
.hp-fill { position: absolute; inset: 0; transform-origin: left; background: linear-gradient(90deg, #4e9fc4, #9ee8ff); transition: transform .08s linear; }
.lane-hud.enemy .hp-fill { transform-origin: right; background: linear-gradient(270deg, #b9523f, #ffa08e); }
.hp-track .shield-fill { position: absolute; inset: 0; background: rgba(200,235,255,.5); transform-origin: left; }
.lane-hud.enemy .hp-track .shield-fill { transform-origin: right; }
.hud-num { display: flex; justify-content: space-between; font-size: 6.5px; color: var(--dim); margin-top: 2px; letter-spacing: .03em; }
.lane-hud.enemy .hud-num { flex-direction: row-reverse; }
.hud-num b { color: #b8becd; font-weight: 600; }
.energy-track { height: 2px; background: rgba(255,255,255,.06); margin-top: 3px; overflow: hidden; }
.energy-fill { height: 100%; width: 0; background: linear-gradient(90deg, #b78cff, #f3d9ff); transition: width .1s linear; }
.lane-hud.enemy .energy-fill { background: linear-gradient(90deg, #ff8f7a, #ffd2c5); }
.lane.hud-dead .hud-portrait { filter: grayscale(1) brightness(.5); }
.lane.hud-dead .hud-name { color: #666c7d; }

.lane-seal {
  position: absolute; left: 50%; top: 5px; transform: translateX(-50%); z-index: 2;
  display: flex; flex-direction: column; align-items: center; gap: 0; pointer-events: none; opacity: .62;
}
.lane-seal .seal-roman { font-family: var(--font-display); font-size: 10px; color: #cbb88b; letter-spacing: .1em; text-shadow: 0 0 10px rgba(0,0,0,.8); }
.lane-seal .seal-name { font-size: 6px; letter-spacing: .18em; text-transform: uppercase; color: var(--terr-color, #9aa1b2); text-shadow: 0 0 8px rgba(0,0,0,.9); }
.lane-targetable { cursor: crosshair; }
.lane.targeting {
  border-color: rgba(217,173,98,.75) !important;
  box-shadow: inset 0 0 0 1px rgba(217,173,98,.55), 0 0 22px rgba(217,173,98,.2);
  animation: targetPulse 1.1s ease-in-out infinite;
}
@keyframes targetPulse { 0%,100% { box-shadow: inset 0 0 0 1px rgba(217,173,98,.5), 0 0 14px rgba(217,173,98,.13); } 50% { box-shadow: inset 0 0 0 1px rgba(217,173,98,.85), 0 0 28px rgba(217,173,98,.28); } }
.lane.swap-first { border-color: rgba(199,155,255,.8) !important; box-shadow: inset 0 0 0 1px rgba(199,155,255,.5); }
.lane.lane-won-ally { border-color: rgba(129,215,255,.4); }
.lane.lane-won-enemy { border-color: rgba(255,139,120,.4); }
.lane-result {
