// ─────────────────────────────────────────────────────────────
//  CHIMERA — core: state, chimera genetics, shared helpers
// ─────────────────────────────────────────────────────────────
import {
  ESSENCES, ESSENCE_BY_ID, FAMILIES, TERRAINS, MUTATIONS, MUTATION_BY_ID,
  LINEUPS, BOONS, STARTING_AETHER, MAX_EMBERS, TOTAL_ROUNDS, ROMAN,
  attachRandomMutation,
} from './data.js'
import { mix } from './creature.js'

export { ESSENCES, ESSENCE_BY_ID, FAMILIES, TERRAINS, MUTATIONS, MUTATION_BY_ID, LINEUPS, BOONS, TOTAL_ROUNDS, ROMAN }
export const $ = (s, p = document) => p.querySelector(s)
export const $$ = (s, p = document) => [...p.querySelectorAll(s)]
export const clamp = (v, a, b) => Math.max(a, Math.min(b, v))
export const cap = s => s.charAt(0).toUpperCase() + s.slice(1)
export const fmt = n => n >= 1000 ? (n / 1000).toFixed(n >= 10000 ? 0 : 1) + 'k' : Math.round(n).toString()
export const rnd = (a, b) => a + Math.random() * (b - a)
export const pick = arr => arr[Math.floor(Math.random() * arr.length)]

export function hashString(str) {
  let h = 2166136261
  for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 16777619) }
  return h >>> 0
}
export function mulberry32(a) {
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0
    let t = Math.imul(a ^ (a >>> 15), 1 | a)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

// ───────────────────────────── event bus ─────────────────────────────
const listeners = {}
export function on(evt, fn) { (listeners[evt] ||= []).push(fn) }
export function emit(evt, data) { (listeners[evt] || []).forEach(fn => fn(data)) }

// ───────────────────────────── sound ─────────────────────────────
export const sound = {
  ctx: null,
  enabled: true,
  lastHit: 0,
  init() {
    if (this.ctx) { if (this.ctx.state === 'suspended') this.ctx.resume(); return }
    try { this.ctx = new (window.AudioContext || window.webkitAudioContext)() } catch { this.ctx = null }
  },
  tone(freq, dur = 0.12, type = 'sine', gain = 0.03, slide = 0, delay = 0) {
    if (!this.enabled || !this.ctx || this.ctx.state !== 'running') return
    const t0 = this.ctx.currentTime + delay
    const o = this.ctx.createOscillator()
    const g = this.ctx.createGain()
    o.type = type
    o.frequency.setValueAtTime(freq, t0)
    if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(30, freq + slide), t0 + dur)
    g.gain.setValueAtTime(0.0001, t0)
    g.gain.exponentialRampToValueAtTime(gain, t0 + 0.012)
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur)
    o.connect(g).connect(this.ctx.destination)
    o.start(t0); o.stop(t0 + dur + 0.02)
  },
  click() { this.tone(520, 0.05, 'triangle', 0.018, 80) },
  hit(crit = false) {
    const now = performance.now()
    if (now - this.lastHit < 45) return
    this.lastHit = now
    this.tone(crit ? 150 : 105, crit ? 0.14 : 0.09, 'triangle', crit ? 0.05 : 0.028, -55)
  },
  cast() {
    this.tone(300, 0.28, 'sine', 0.03, 520)
    this.tone(600, 0.22, 'triangle', 0.015, 300, 0.04)
  },
  fuse() {
    [261.6, 329.6, 392, 523.3].forEach((f, i) => this.tone(f, 0.5, 'sine', 0.022, 0, i * 0.06))
  },
  breach(ally = true) {
    [392, 523, 659, 784].forEach((f, i) => this.tone(f, 0.5, 'triangle', 0.022, 0, i * 0.07))
    this.tone(ally ? 98 : 73, 0.5, 'sine', 0.05, -20)
  },
  win() {
    [261.6, 392, 523.3, 659.3, 784].forEach((f, i) => this.tone(f, 0.9, 'sine', 0.026, 0, i * 0.1))
  },
  lose() {
    [220, 174.6, 146.8, 110].forEach((f, i) => this.tone(f, 0.8, 'triangle', 0.03, -20, i * 0.14))
  },
}

// ───────────────────────────── run state ─────────────────────────────
const defaultMods = () => ({
  hp: 1, atk: 1, aspd: 1, crit: 0, leech: 0, shield: 0, energy: 1,
  cdr: 1, starfall: 1, shifts: 0, mutations: 0, healing: 0,
})

export const state = {
  view: 'prep',
  round: 1,
  aether: STARTING_AETHER,
  embers: MAX_EMBERS,
  fighters: Array(5).fill(null),
  prime: 'wolf',
  seed: 'phoenix',
  selectedLane: 0,
  lineup: [],
  boons: [],
  runMods: defaultMods(),
  stats: { fusions: 0, roundsWon: 0, laneWins: 0, laneLosses: 0, damage: 0, battles: 0 },
  battle: null,
  runOver: false,
  soundOn: true,
  retrying: false,
}

export function resetRun() {
  state.view = 'prep'
  state.round = 1
  state.aether = STARTING_AETHER
  state.embers = MAX_EMBERS
  state.fighters = Array(5).fill(null)
  state.prime = 'wolf'
  state.seed = 'phoenix'
  state.selectedLane = 0
  state.boons = []
  state.runMods = defaultMods()
  state.stats = { fusions: 0, roundsWon: 0, laneWins: 0, laneLosses: 0, damage: 0, battles: 0 }
  state.battle = null
  state.runOver = false
  state.retrying = false
  state.lineup = buildEnemyLineup(1)
  try { state.soundOn = localStorage.getItem('chimera-sound') !== 'off' } catch { state.soundOn = true }
}

export function currentLineupDef() { return LINEUPS[state.round - 1] }
export function terrainFor(lane) { return TERRAINS[lane] }
export function familyInfo(id) { return FAMILIES[id] || { name: id, color: '#9fd0ff', soft: '#dce9ff' } }

// ───────────────────────────── fighter construction ─────────────────────────────
function basePassive(f) {
  const k = f.passive?.key
  f.flags ||= {}
  if (k === 'thickhide') f.armor += 10
  if (k === 'bulwark') { f.armor += 10; f.shieldPower *= 1.2 }
  if (k === 'airborne') f.dodge += 0.15
  if (k === 'predator') f.crit += 15
  if (k === 'livingstone') f.battleShield += 0.10
  if (k === 'soulsiphon') f.lifesteal += 0.15
  if (k === 'tyrantscale') f.armor += 10
  if (k === 'ashcycle') f.flags.reborn = true
}

function applyMutation(f, id) {
  const m = MUTATION_BY_ID[id]
  if (!m || f.mutations.includes(id)) return false
  f.mutations.push(id)
  f.flags ||= {}
  m.apply(f)
  return true
}

function applyTerrain(f, laneIndex) {
  const terr = TERRAINS[laneIndex]
  if (!terr) return
  if (!f.lineage.includes(terr.family)) return
  f.resonant = { id: terr.id, name: terr.name, desc: terr.desc, color: terr.color, family: terr.family }
  if (terr.bonus.hp) f.maxHp *= terr.bonus.hp
  if (terr.bonus.atk) f.atk *= terr.bonus.atk
  if (terr.bonus.aspd) f.interval /= terr.bonus.aspd
  if (terr.bonus.energy) f.energyMult *= terr.bonus.energy
}

function roleFrom(f) {
  if (f.maxHp > 1080 && f.interval > 1.15) return 'Vanguard'
  if (f.interval <= 0.88) return 'Skirmisher'
  if (f.rangeType === 'ranged' && f.atk > 72) return 'Mystic'
  if (f.atk > 82) return 'Juggernaut'
  if (f.crit > 18) return 'Assassin'
  return 'Duelist'
}

function randomMutations(f, rng, count) {
  const pool = MUTATIONS.filter(m => !f.mutations.includes(m.id) && !(m.id === f.lastMutation))
  for (let i = 0; i < count; i++) {
    const available = pool.filter(m => !f.mutations.includes(m.id))
    if (!available.length) break
    const m = available[Math.floor(rng() * available.length)]
    applyMutation(f, m.id)
  }
}

function finalizeFighter(f, opts = {}) {
  const {
    laneIndex = 0, scale = 1, rng = Math.random, mutations = null,
    name = null, title = null, isPlayer = false, boss = false,
  } = opts
  basePassive(f)
  if (mutations && mutations.length) {
    mutations.forEach(id => applyMutation(f, id))
  } else {
    let count = f.isPureblood ? 1 : 1 + (rng() < 0.48 ? 1 : 0)
    if (isPlayer && state.runMods.mutations) count += state.runMods.mutations
    randomMutations(f, rng, count)
  }
  f.maxHp = Math.max(320, Math.round(f.maxHp * scale))
  f.atk = Math.max(24, Math.round(f.atk * scale * 10) / 10)
  f.interval = Math.max(0.45, Math.round(f.interval * 1000) / 1000)
  f.armor = Math.round(clamp(f.armor, 0, 55))
  f.crit = Math.round(clamp(f.crit, 0, 60))
  f.lifesteal = Math.round(f.lifesteal * 100) / 100
  f.dodge = Math.round(f.dodge * 100) / 100
  f.thorns = Math.round(f.thorns * 100) / 100
  f.shieldPower = Math.round(f.shieldPower * 100) / 100
  f.energyMult = Math.round(f.energyMult * 100) / 100
  f.battleShield = Math.round(f.battleShield * 100) / 100
  applyTerrain(f, laneIndex)
  f.maxHp = Math.round(f.maxHp)
  f.atk = Math.round(f.atk * 10) / 10
  f.hp = f.maxHp
  f.role = roleFrom(f)
  if (name) f.name = name
  if (title) f.title = title
  f.laneIndex = laneIndex
  f.isPlayer = isPlayer
  f.isEnemy = !isPlayer
  f.isBoss = boss
  f.level = state.round
  f.phaseOffset = rng() * 6
  f.power = powerOf(f)
  return f
}

export function makeChimera(primeId, seedId, opts = {}) {
  const a = ESSENCE_BY_ID[primeId]
  const b = ESSENCE_BY_ID[seedId]
  const rng = opts.rng || Math.random
  const pure = a.family === b.family
  const f = {
    id: `${primeId}-${seedId}-${opts.laneIndex ?? 0}`,
    name: cap(a.prefix + b.suffix),
    title: a.epithet,
    family: a.family,
    family2: b.family !== a.family ? b.family : null,
    lineage: [...new Set([a.family, b.family])],
    silhouette: a.silhouette,
    extra: b.silhouette !== a.silhouette ? b.silhouette : null,
    extraAccent: b.accent,
    color: mix(a.color, b.color, 0.34),
    accent: mix(a.accent, b.accent, 0.25),
    deep: mix(a.deep, b.deep, 0.4),
    soft: mix(mix(a.color, b.color, 0.34), '#ffffff', 0.55),
    role: 'Duelist',
    maxHp: ((a.hp + b.hp) / 2) * 1.07 * (pure ? 1.12 : 1),
    atk: ((a.atk + b.atk) / 2) * 1.07 * (pure ? 1.12 : 1),
    interval: ((a.interval + b.interval) / 2) * (pure ? 0.95 : 0.98),
    armor: Math.round((a.armor + b.armor) / 2),
    crit: Math.round((a.crit + b.crit) / 2),
    lifesteal: 0,
    dodge: 0,
    thorns: 0,
    battleShield: 0,
    shieldPower: 1,
    energyMult: 1,
    rangeType: (a.range === 'ranged' || b.range === 'ranged') ? 'ranged' : 'melee',
    ability: { ...a.ability, power: pure ? 1.22 : 1 },
    passive: { ...b.passive },
    abilitySource: a.name,
    passiveSource: b.name,
    primeId, seedId,
    flags: {},
    mutations: [],
    isPureblood: pure,
    abilityPower: pure ? 1.22 : 1,
    resonant: null,
  }
  if (primeId === seedId) f.name = 'Elder ' + a.name
  if (opts.name) f.name = opts.name
  if (opts.title) f.title = opts.title
  return finalizeFighter(f, opts)
}

export function makeEssenceEnemy(essenceId, opts = {}) {
  const e = ESSENCE_BY_ID[essenceId]
  const f = {
    id: `enemy-${essenceId}-${opts.laneIndex ?? 0}`,
    name: e.name,
    title: e.epithet,
    family: e.family,
    family2: null,
    lineage: [e.family],
    silhouette: e.silhouette,
    extra: null,
    extraAccent: e.accent,
    color: e.color,
    accent: e.accent,
    deep: e.deep,
    soft: mix(e.color, '#ffffff', 0.55),
    role: e.role,
    maxHp: e.hp,
    atk: e.atk,
    interval: e.interval,
    armor: e.armor,
    crit: e.crit,
    lifesteal: 0,
    dodge: 0,
    thorns: 0,
    battleShield: 0,
    shieldPower: 1,
    energyMult: 1,
    rangeType: e.range,
    ability: { ...e.ability, power: 1 },
    passive: { ...e.passive },
    abilitySource: e.name,
    passiveSource: e.name,
    flags: {},
    mutations: [],
    isPureblood: false,
    abilityPower: 1,
    resonant: null,
  }
  return finalizeFighter(f, opts)
}

export function buildEnemyLineup(round) {
  const def = LINEUPS[round - 1]
  return def.units.map((u, i) => {
    let f
    if (u.fusion) {
      f = makeChimera(u.fusion[0], u.fusion[1], {
        laneIndex: i, scale: u.scale, mutations: u.mutations || [],
        name: u.name, title: u.title, rng: mulberry32(hashString(`boss-${round}-${i}`)),
        boss: !!u.boss,
      })
    } else {
      f = makeEssenceEnemy(u.essence, {
        laneIndex: i, scale: u.scale, mutations: u.mutations || null,
        rng: mulberry32(hashString(`foe-${round}-${i}-${u.name}`)),
        name: u.name, title: u.title,
      })
    }
    f.level = round
    return f
  })
}

export function cloneFighter(f) {
  if (!f) return null
  return {
    ...f,
    flags: { ...f.flags },
    mutations: [...f.mutations],
    resonant: f.resonant ? { ...f.resonant } : null,
    ability: { ...f.ability },
    passive: { ...f.passive },
  }
}

export function effectivePlayer(f) {
  const c = cloneFighter(f)
  const m = state.runMods
  c.maxHp = Math.round(f.maxHp * m.hp)
  c.hp = c.maxHp
  c.atk = Math.round(f.atk * m.atk * 10) / 10
  c.interval = Math.max(0.3, f.interval / m.aspd)
  c.crit = f.crit + m.crit
  c.lifesteal = f.lifesteal + m.leech
  c.battleShield = f.battleShield + m.shield
  c.energyMult = f.energyMult * m.energy
  c.shieldPower = f.shieldPower * (1 + m.healing)
  c.role = f.role
  return c
}

export function powerOf(f) {
  const armorEff = 1 + clamp(f.armor || 0, 0, 60) / 100 * 0.85
  const dodgeEff = 1 + (f.dodge || 0) * 0.7
  const shieldEff = 1 + (f.battleShield || 0) * 0.8
  const ehp = f.maxHp * armorEff * dodgeEff * shieldEff
  const dps = (f.atk / Math.max(0.3, f.interval)) * (1 + (f.crit || 0) / 100 * 0.55)
  return Math.round(ehp * 0.5 + dps * 5.6 + (f.lifesteal || 0) * ehp * 0.5 + (f.shieldPower || 1) * 22)
}

export function previewChimera(laneIndex) {
  if (!state.prime || !state.seed) return null
  const key = `${state.prime}|${state.seed}|${laneIndex}|${state.round}|${state.stats.fusions}|${state.runMods.mutations}`
  return makeChimera(state.prime, state.seed, {
    laneIndex, rng: mulberry32(hashString(key)), isPlayer: true,
  })
}

export function fighterStatLine(f) {
  return { hp: f.maxHp, atk: f.atk, aspd: 1 / f.interval, armor: f.armor, crit: f.crit, range: f.rangeType }
}

// ───────────────────────────── toast ─────────────────────────────
let toastTimer = null
export function toast(text, bad = false) {
  const stack = $('#toastStack')
  if (!stack) return
  const el = document.createElement('div')
  el.className = 'toast' + (bad ? ' bad' : '')
  el.textContent = text
  stack.appendChild(el)
  while (stack.children.length > 3) stack.firstChild.remove()
  setTimeout(() => { el.style.opacity = '0'; el.style.transform = 'translateY(6px)'; el.style.transition = '.3s'; setTimeout(() => el.remove(), 320) }, 2500)
}

export function updateSoundButton() {
  document.body.classList.toggle('muted', !state.soundOn)
}

export function setSound(on) {
  state.soundOn = on
  sound.enabled = on
  updateSoundButton()
  try { localStorage.setItem('chimera-sound', on ? 'on' : 'off') } catch {}
}

export function attachBoonMutation(fighter) {
  return attachRandomMutation(fighter)
}

// ─────────────────────────────────────────────────────────────
//  CHIMERA — fusion lab
// ─────────────────────────────────────────────────────────────
import {
  state, $, $$, clamp, cap, fmt, ROMAN, TERRAINS, ESSENCES, ESSENCE_BY_ID,
  FAMILIES, MUTATION_BY_ID, TOTAL_ROUNDS, sound, toast, emit,
  effectivePlayer, powerOf, previewChimera, buildEnemyLineup, familyInfo, terrainFor,
  on,
} from './core.js'
import { renderPortrait, drawPortraitFrame } from './creature.js'
import { startBattle } from './battle.js'

let previewTarget = null
let previewRaf = null

export function showPrep() {
  state.view = 'prep'
  state.battle = null
  $('#prepView').classList.remove('hidden')
  $('#battleView').classList.add('hidden')
  updateHeader()
  renderPrep()
  if (!previewRaf) previewRaf = requestAnimationFrame(animatePreview)
}

function animatePreview(now) {
  previewRaf = requestAnimationFrame(animatePreview)
  if (state.view !== 'prep' || !previewTarget) return
  const { canvas, fighter, size } = previewTarget
  if (!canvas.isConnected) { previewTarget = null; return }
  drawPortraitFrame(canvas, fighter, { size, t: now / 1000, animate: true })
}

export function updateHeader() {
  const def = state.lineup[state.round - 1]
  $('#roundLabel').textContent = `TRIAL ${ROMAN[state.round - 1] || 'I'} / V`
  $('#roundTitle').textContent = def ? def.name : 'THE THORNWILD'
  $('#aetherCount').textContent = state.aether
  $('#emberCount').textContent = state.embers
  const pips = $('#roundPips')
  pips.innerHTML = ''
  for (let i = 0; i < TOTAL_ROUNDS; i++) {
    const d = document.createElement('span')
    d.className = 'round-pip'
    if (i < state.stats.roundsWon) d.classList.add('done')
    else if (i === state.round - 1 && !state.runOver) d.classList.add('current')
    else if (i === state.round - 1 && state.runOver) d.classList.add('failed')
    pips.appendChild(d)
  }
}

export function initPrep() {
  buildEssenceGrid()
  $('#battleBtn').addEventListener('click', () => {
    if (state.fighters.some(f => !f)) {
      toast('Every lane must be garrisoned.', true)
      return
    }
    sound.click()
    startBattle()
  })
  on('runReset', () => { previewTarget = null; showPrep() })
}

// ───────────────────────── essence vault ─────────────────────────
function buildEssenceGrid() {
  const grid = $('#essenceGrid')
  grid.innerHTML = ''
  for (const e of ESSENCES) {
    const fam = familyInfo(e.family)
    const card = document.createElement('button')
    card.className = 'essence-card'
    card.dataset.id = e.id
    card.title = `${e.name} — ${fam.name} ${e.role}\nPrime active: ${e.ability.name} — ${e.ability.desc}\nSeed passive: ${e.passive.name} — ${e.passive.desc}`
    card.innerHTML = `
      <span class="e-art"></span>
      <span class="e-copy">
        <span class="e-name">${e.name}</span>
        <span class="e-meta"><span class="family-dot" style="background:${fam.color};box-shadow:0 0 5px ${fam.color}"></span>${fam.name}<span class="e-role">· ${e.role}</span></span>
      </span>
      <span class="pick-badge hidden">I</span>`
    const art = card.querySelector('.e-art')
    const canvas = document.createElement('canvas')
    art.appendChild(canvas)
    renderPortrait(canvas, e, { size: 84, ring: true, showPedestal: false, pickT: 1.1 })
    card.addEventListener('click', () => selectEssence(e.id))
    grid.appendChild(card)
  }
}

function selectEssence(id) {
  sound.click()
  if (state.prime === id) {
    state.prime = null
  } else if (!state.prime) {
    state.prime = id
  } else if (state.seed === id) {
    state.seed = null
  } else if (!state.seed) {
    state.seed = id
  } else {
    state.seed = id
  }
  renderPrep()
}

function renderEssenceSelection() {
  $$('#essenceGrid .essence-card').forEach(card => {
    const id = card.dataset.id
    card.classList.toggle('selected-prime', state.prime === id)
    card.classList.toggle('selected-seed', state.seed === id)
    const badge = card.querySelector('.pick-badge')
    if (state.prime === id) { badge.classList.remove('hidden'); badge.textContent = 'I'; badge.style.background = '#d9ad62' }
    else if (state.seed === id) { badge.classList.remove('hidden'); badge.textContent = 'II'; badge.style.background = '#7fe3ac' }
    else badge.classList.add('hidden')
  })
}

function renderLineageSlots() {
  const wrap = $('#lineageSlots')
  const a = state.prime ? ESSENCE_BY_ID[state.prime] : null
  const b = state.seed ? ESSENCE_BY_ID[state.seed] : null
  const slot = (which, essence, label) => {
    const fam = essence ? familyInfo(essence.family) : null
    return `
      <div class="lineage-slot ${which} ${essence ? 'filled' : 'empty'}" data-slot="${which}">
        <span class="slot-mark">${which === 'prime' ? 'I' : 'II'}</span>
        ${essence ? `<span class="slot-swatch" style="background:${fam.color};box-shadow:0 0 8px ${fam.color}66"></span>` : ''}
        <span class="slot-text">
          <span class="slot-label">${label}</span>
          <span class="slot-name">${essence ? essence.name : 'Choose essence'}</span>
        </span>
        ${essence ? '<button class="slot-x" data-clear="' + which + '" aria-label="Clear ' + label + '">×</button>' : ''}
      </div>`
  }
  wrap.innerHTML = slot('prime', a, 'Prime · Active') + slot('seed', b, 'Seed · Passive')
  $$('#lineageSlots [data-clear]').forEach(btn => btn.addEventListener('click', ev => {
    ev.stopPropagation()
    if (btn.dataset.clear === 'prime') state.prime = null
    else state.seed = null
    sound.click()
    renderPrep()
  }))
  $('#essenceHint').textContent = !state.prime ? 'Choose the PRIME' : !state.seed ? 'Choose the SEED' : 'Both essences chosen'
}

// ───────────────────────── fusion preview ─────────────────────────
function fuseBlockReason(lane) {
  if (!state.prime || !state.seed) return 'Choose two essences first'
  if (state.aether < 1) return 'No Aether remains'
  if (!lane && lane !== 0) return 'Mark a lane'
  const occupied = !!state.fighters[lane]
  const empties = state.fighters.filter(f => !f).length
  if (occupied && empties > 0) return 'Mark an empty lane'
  if (occupied && empties === 0) return null
  return null
}

export function renderFusionPreview() {
  const body = $('#fusionPreview')
  const lane = state.selectedLane
  const prime = state.prime ? ESSENCE_BY_ID[state.prime] : null
  const seed = state.seed ? ESSENCE_BY_ID[state.seed] : null
  previewTarget = null

  if (!prime || !seed) {
    const chosen = prime || seed
    body.innerHTML = `
      <div class="forge-empty">
        <div class="forge-sigil"><span class="ring"></span><span class="ring"></span><span class="ring"></span><span class="core"></span></div>
        <h3>${chosen ? 'THE CHAMBER HUNGERS' : 'BEGIN THE BINDING'}</h3>
        <p>${chosen
          ? `You have offered <strong style="color:#d9c9a4">${chosen.name}</strong> as ${prime ? 'the Prime. Its active power will lead the fusion.' : 'the Seed. Its instinct will root the fusion.'}<br>Choose ${prime ? 'a Seed' : 'a Prime'} to reveal the chimera.`
          : 'Choose two essences from the vault. The first lends its active power; the second lends its passive instinct. Cross-lineage fusions always mutate.'}</p>
        <div class="lineage-pair"><span class="ghost-slot">I</span><span>✕</span><span class="ghost-slot">II</span><span style="color:#5e6478;font-size:9px;letter-spacing:.1em">→ ?</span></div>
      </div>`
    $('#forgeSub').textContent = chosen ? 'One half of the pattern is set' : 'The chamber is listening'
    return
  }

  const preview = previewChimera(lane)
  if (!preview) return
  const disp = effectivePlayer(preview)
  const enemy = state.lineup[lane]
  const terr = TERRAINS[lane]
  const pFam = familyInfo(prime.family)
  const sFam = familyInfo(seed.family)
  const block = fuseBlockReason(lane)
  const occupied = !!state.fighters[lane]
  const empties = state.fighters.filter(f => !f).length
  const dim = (occupied && empties > 0) ? true : false
  const pw = powerOf(disp)
  const ep = enemy ? powerOf(enemy) : 0
  const ratio = ep ? pw / ep : 2
  const matchLabel = ratio >= 1.14 ? 'FAVOURED' : ratio <= 0.88 ? 'RISKY' : 'EVEN'
  const matchClass = ratio >= 1.14 ? '' : ratio <= 0.88 ? 'risky' : 'even'
  const laneTitle = `LANE ${ROMAN[lane]} — ${terr.name}`
  const muts = preview.mutations.map(id => MUTATION_BY_ID[id]).filter(Boolean)
  const ability = preview.ability
  const passive = preview.passive
  const buttonLabel = block
    ? block.toUpperCase()
    : occupied ? 'REPLACE & DEPLOY' : `FUSE & DEPLOY TO LANE ${ROMAN[lane]}`

  body.innerHTML = `
    <div class="forge-result">
      <div class="forge-hero">
        <div class="forge-portrait"><canvas></canvas></div>
        <div class="forge-id">
          <div class="lineage-mini">
            <b>${prime.name}</b><i>×</i><b>${seed.name}</b>
            ${preview.family2 ? `<i>·</i><span>${pFam.name} / ${sFam.name}</span>` : `<i>·</i><span>Pureblood</span>`}
          </div>
          <div class="forge-name">${preview.name}</div>
          <div class="forge-epithet">${preview.title || prime.epithet}</div>
          <div class="forge-badges">
            <span class="chip gold">${preview.role}</span>
            <span class="chip">${pFam.name}${preview.family2 ? ' / ' + sFam.name : ' lineage'}</span>
            <span class="chip">${preview.rangeType === 'ranged' ? 'Ranged' : 'Melee'}</span>
            ${preview.isPureblood ? '<span class="chip green">Pureblood</span>' : ''}
            ${preview.resonant ? `<span class="chip" style="color:${terr.color};border-color:${terr.color}55">Resonant</span>` : ''}
          </div>
          <div class="forge-power"><span>POWER</span><b>${pw}</b><em>vs ${ep || '—'} ${enemy ? 'in lane' : ''}</em></div>
        </div>
      </div>

      <div class="stat-grid">
        <div class="stat-box"><span>Vitality</span><b>${fmt(disp.maxHp)}</b><i style="width:${clamp(disp.maxHp / 2200 * 100, 8, 100)}%"></i></div>
        <div class="stat-box"><span>Attack</span><b>${Math.round(disp.atk)}</b><i style="width:${clamp(disp.atk / 130 * 100, 8, 100)}%"></i></div>
        <div class="stat-box"><span>Cadence</span><b>${(1 / disp.interval).toFixed(2)}<small style="font-size:7px;color:#5e6478">/s</small></b><i style="width:${clamp((1 / disp.interval) / 2.2 * 100, 8, 100)}%"></i></div>
        <div class="stat-box"><span>Armour</span><b>${disp.armor}%</b><i style="width:${clamp(disp.armor / 55 * 100, 6, 100)}%"></i></div>
      </div>

      <div class="trait-list">
        <div class="trait">
          <span class="trait-icon">✦</span>
          <div class="trait-copy"><b>${ability.name}<em>Prime active</em></b><p>${ability.desc}${preview.isPureblood ? ' <span style="color:#7fe3ac">Empowered by pure blood.</span>' : ''}</p></div>
        </div>
        <div class="trait passive">
          <span class="trait-icon">❖</span>
          <div class="trait-copy"><b>${passive.name}<em>Seed passive</em></b><p>${passive.desc}</p></div>
        </div>
        ${muts.map(m => `<div class="trait mutation"><span class="trait-icon">☣</span><div class="trait-copy"><b>${m.name}<em>Mutation</em></b><p>${m.desc}</p></div></div>`).join('')}
      </div>

      <div class="resonance-note" style="--res-color:${terr.color}">
        <span class="res-glyph">◈</span>
        <span>${preview.resonant
          ? `<b>${terr.name}</b> resonates — ${terr.desc} woven into this chimera.`
          : `<b>${terr.name}</b> lies dormant — this lineage earns no terrain blessing here.`}</span>
      </div>

      ${enemy ? `<div class="matchup"><span>${laneTitle} · VS ${enemy.name}</span><b class="${matchClass}">${matchLabel}</b></div>` : ''}

      <button class="fuse-btn" id="fuseBtn" ${block ? 'disabled' : ''}>
        <span class="sheen"></span>
        ${buttonLabel}
        ${!block ? '<small>◆ 1 AETHER · THE PATTERN WILL HOLD</small>' : ''}
      </button>
    </div>`

  const canvas = body.querySelector('.forge-portrait canvas')
  renderPortrait(canvas, preview, { size: 300, ring: true, showPedestal: true })
  previewTarget = { canvas, fighter: preview, size: 300 }
  $('#forgeSub').textContent = `${laneTitle} · ${preview.mutations.length} mutation${preview.mutations.length === 1 ? '' : 's'}`
  const fuseBtn = $('#fuseBtn')
  if (fuseBtn) fuseBtn.addEventListener('click', doFuse)
  if (dim) {
    // The lane is occupied while others remain empty. Make the reason explicit.
    $('#forgeSub').textContent = 'That lane is already garrisoned'
  }
}

function doFuse() {
  const lane = state.selectedLane
  const block = fuseBlockReason(lane)
  if (block) { toast(block, true); return }
  const preview = previewChimera(lane)
  if (!preview) return
  preview.isPlayer = true
  preview.isEnemy = false
  preview.laneIndex = lane
  state.fighters[lane] = preview
  state.aether -= 1
  state.stats.fusions += 1
  sound.fuse()
  toast(`${preview.name} is bound to Lane ${ROMAN[lane]}`)
  const panel = $('.forge-panel')
  panel.classList.remove('fusing')
  void panel.offsetWidth
  panel.classList.add('fusing')
  setTimeout(() => panel.classList.remove('fusing'), 700)

  state.prime = null
  state.seed = null
  const nextEmpty = state.fighters.findIndex(f => !f)
  if (nextEmpty >= 0) state.selectedLane = nextEmpty
  renderPrep()
  if (state.fighters.every(Boolean)) toast('The covenant is complete. The horn awaits.')
}

// ───────────────────────── lane list ─────────────────────────
function renderLaneList() {
  const list = $('#laneList')
  list.innerHTML = ''
  const empties = state.fighters.filter(f => !f).length
  for (let i = 0; i < 5; i++) {
    const terr = TERRAINS[i]
    const enemy = state.lineup[i]
    const fighter = state.fighters[i]
    const disp = fighter ? effectivePlayer(fighter) : null
    const selectable = !fighter || empties === 0
    const card = document.createElement('button')
    card.className = 'lane-card' + (state.selectedLane === i ? ' selected' : '') + (fighter ? ' occupied' : '')
    card.dataset.lane = i
    card.innerHTML = `
      <span class="lane-ident">
        <span class="lane-roman">${ROMAN[i]}</span>
        <span class="terrain-name">${terr.name}</span>
        <span class="terrain-bonus" style="--terr-color:${terr.color}">${terr.desc}</span>
      </span>
      <span class="unit-chip ally ${fighter ? '' : 'empty'}">
        ${fighter ? '<span class="u-art"></span>' : '<span class="u-art">?</span>'}
        <span class="u-copy">
          <span class="u-name">${fighter ? fighter.name : 'Unbound'}</span>
          <span class="u-stat">${fighter ? `<b>${fmt(disp.maxHp)}</b> HP · <b>${Math.round(disp.atk)}</b> ATK` : 'Awaiting chimera'}</span>
        </span>
        ${fighter && fighter.resonant ? `<span class="res-mark" style="--terr-color:${terr.color}" title="Resonant: ${terr.desc}">◈</span>` : ''}
      </span>
      <span class="vs-mark">VS</span>
      <span class="unit-chip enemy" title="${enemy.ability.name} — ${enemy.ability.desc}">
        <span class="u-art"></span>
        <span class="u-copy">
          <span class="u-name">${enemy.name}</span>
          <span class="u-stat"><b>${fmt(enemy.maxHp)}</b> HP · PWR <b>${powerOf(enemy)}</b></span>
        </span>
        ${enemy.resonant ? `<span class="res-mark" style="--terr-color:${terr.color}" title="Enemy resonance: ${terr.desc}">◈</span>` : ''}
      </span>
      <span class="lane-status">${selectable ? 'TARGET' : 'GARRISONED'}</span>`
    list.appendChild(card)

    const art = card.querySelector('.unit-chip.ally .u-art')
    if (fighter && art) {
      const c = document.createElement('canvas')
      art.appendChild(c)
      renderPortrait(c, fighter, { size: 74, ring: true, showPedestal: false })
    }
    const eArt = card.querySelector('.unit-chip.enemy .u-art')
    const ec = document.createElement('canvas')
    eArt.appendChild(ec)
    renderPortrait(ec, enemy, { size: 74, ring: true, showPedestal: false })

    card.addEventListener('click', () => {
      if (!selectable) {
        toast('That lane is garrisoned. Choose an empty lane.', true)
        return
      }
      state.selectedLane = i
      sound.click()
      renderPrep()
    })
  }
  $('#laneCount').textContent = `${5 - empties} / 5`
  $('#deploySub').textContent = empties ? `Garrison every lane · ${empties} remaining` : 'The covenant is complete'
}

// ───────────────────────── overall prep ─────────────────────────
export function renderPrep() {
  updateHeader()
  renderEssenceSelection()
  renderLineageSlots()
  renderFusionPreview()
  renderLaneList()
  const filled = state.fighters.filter(Boolean).length
  const ready = filled === 5
  const btn = $('#battleBtn')
  btn.disabled = !ready
  const hint = $('#deployHint')
  if (ready) {
    hint.textContent = 'The covenant is complete. Sound the horn.'
    hint.classList.add('ready')
  } else {
    hint.textContent = state.aether < 1
      ? 'No Aether remains. Return with the next dawn.'
      : 'All five lanes must be garrisoned before the horn sounds.'
    hint.classList.remove('ready')
  }
  $('#stepTrack')?.querySelectorAll('.step').forEach(step => {
    const n = +step.dataset.step
    const both = state.prime && state.seed
    const laneOk = state.selectedLane != null && fuseBlockReason(state.selectedLane) === null
    step.classList.toggle('active', n === 1 ? !both : n === 2 ? (both && !laneOk) : (both && laneOk))
  })
}

export function healFighters() {
  state.fighters.forEach(f => { if (f) { f.hp = f.maxHp } })
}

// ─────────────────────────────────────────────────────────────
//  CHIMERA — five-lane battle
// ─────────────────────────────────────────────────────────────
import {
  state, $, $$, clamp, fmt, ROMAN, TERRAINS, sound, toast, emit,
  cloneFighter, familyInfo, terrainFor, rnd,
} from './core.js'
import { drawCreature } from './creature.js'

const BATTLE_TIME = 60

const COMMANDS = [
  { id: 'rally', key: 'Q', name: 'RALLY', icon: '⚑', desc: '+35% attack speed · 5s', cd: 18 },
  { id: 'aegis', key: 'W', name: 'AEGIS', icon: '◈', desc: '+30% max-HP shield', cd: 22 },
  { id: 'starfall', key: 'E', name: 'STARFALL', icon: '☄', desc: 'Call a meteor onto a lane', cd: 16 },
  { id: 'shift', key: 'R', name: 'SHIFT', icon: '⇄', desc: 'Swap two fighters', cd: 0 },
]

let raf = null
let lastFrame = 0
let resizeTimer = null
let keyBound = false

// ───────────────────────────── setup ─────────────────────────────
export function startBattle() {
  if (state.fighters.some(f => !f)) return
  state.view = 'battle'
  state.stats.battles += 1
  $('#prepView').classList.add('hidden')
  $('#battleView').classList.remove('hidden')

  const ally = state.fighters.map((f, i) => makeBattleFighter(f, 'ally', i))
  const enemy = state.lineup.map((f, i) => makeBattleFighter(f, 'enemy', i))
  const bl = {
    lanes: [],
    t: 0,
    time: BATTLE_TIME,
    phase: 'intro',
    introT: 2.2,
    score: { ally: 0, enemy: 0 },
    speed: 1,
    mode: null,
    ended: false,
    revealAt: 0,
    hudT: 0,
    damageDealt: 0,
    commands: {
      rally: { remain: 0, max: COMMANDS[0].cd * state.runMods.cdr },
      aegis: { remain: 0, max: COMMANDS[1].cd * state.runMods.cdr },
      starfall: { remain: 0, max: COMMANDS[2].cd * state.runMods.cdr },
      shift: { remain: 0, max: 0 },
    },
    shiftCharges: 1 + state.runMods.shifts,
  }
  state.battle = bl

  for (let i = 0; i < 5; i++) {
    bl.lanes.push(makeLane(i, ally[i], enemy[i], bl))
  }

  buildArena(bl)
  buildCommands(bl)
  updateScorePips(bl)
  setPhaseText('THE HORN SOUNDS')
  showBanner('THE HORN SOUNDS', 'I')
  $('#speedBtn').textContent = '1×'
  $('#speedBtn').onclick = () => {
    if (!state.battle) return
    state.battle.speed = state.battle.speed === 1 ? 2 : 1
    $('#speedBtn').textContent = state.battle.speed + '×'
    sound.click()
  }
  bindKeys()
  lastFrame = performance.now()
  if (!raf) raf = requestAnimationFrame(loop)
  requestAnimationFrame(layoutLanes)
  sound.init()
}

export function stopBattle() {
  if (raf) cancelAnimationFrame(raf)
  raf = null
}

function makeBattleFighter(src, side, laneIndex) {
  const f = cloneFighter(src)
  if (side === 'ally') {
    const m = state.runMods
    f.maxHp = Math.round(src.maxHp * m.hp)
    f.atk = Math.round(src.atk * m.atk * 10) / 10
    f.interval = Math.max(0.3, src.interval / m.aspd)
    f.crit = src.crit + m.crit
    f.lifesteal = src.lifesteal + m.leech
    f.battleShield = src.battleShield + m.shield
    f.energyMult = src.energyMult * m.energy
    f.shieldPower = src.shieldPower * (1 + m.healing)
  }
  f.hp = f.maxHp
  f.side = side
  f.x = side === 'ally' ? 0.18 : 0.82
  f.attackTimer = 0.3 + Math.random() * 0.45
  f.energy = 10 + Math.random() * 14
  f.shield = Math.round(f.maxHp * (f.battleShield || 0))
  f.shieldUntil = Infinity
  f.dead = false
  f.status = {
    stunUntil: 0, slowUntil: 0, slowAmt: 0,
    aspdUntil: 0, aspdMult: 1, thornsUntil: 0, thornsAmt: 0,
    dots: [],
  }
  f.anim = { atkT: 0, hitT: 0, castT: 0, deadT: 0 }
  f.attackCount = 0
  f.damageDealt = 0
  f.damageTaken = 0
  f.heals = 0
  f.kills = 0
  f.rebornUsed = false
  f.lastHitBy = null
  f.castName = ''
  f.castT = 0
  f.moving = false
  f.rangeType = f.rangeType || (f.rangeType === 'ranged' ? 'ranged' : 'melee')
  return f
}

function makeLane(index, ally, enemy, bl) {
  const lane = {
    index, ally, enemy, bl,
    el: null, canvas: null, ctx: null, W: 0, H: 0, dpr: 1,
    bgCanvas: null, hud: { ally: null, enemy: null },
    resolved: false, winner: null, phase: 'fight', pushT: 0,
    fx: { particles: [], texts: [], projectiles: [], rings: [], slashes: [], meteors: [], shake: 0 },
  }
  return lane
}

function buildArena(bl) {
  const arena = $('#arena')
  arena.innerHTML = ''
  bl.lanes.forEach((lane, i) => {
    const terr = TERRAINS[i]
    const el = document.createElement('div')
    el.className = 'lane lane-targetable'
    el.dataset.lane = i
    el.innerHTML = `
      <canvas class="lane-canvas"></canvas>
      <div class="lane-seal">
        <span class="seal-roman">${ROMAN[i]}</span>
        <span class="seal-name" style="--terr-color:${terr.color}">${terr.name}</span>
      </div>
      <div class="lane-hud ally" data-side="ally"></div>
      <div class="lane-hud enemy" data-side="enemy"></div>
      <div class="lane-result"><span class="stamp">BREACHED</span></div>`
    lane.el = el
    lane.canvas = el.querySelector('.lane-canvas')
    lane.ctx = lane.canvas.getContext('2d')
    arena.appendChild(el)
    renderRail(lane, 'ally')
    renderRail(lane, 'enemy')
    el.addEventListener('click', () => laneClicked(i))
  })
  const banner = document.createElement('div')
  banner.className = 'battle-banner hidden'
  banner.id = 'battleBanner'
  banner.innerHTML = '<span class="banner-kicker"></span><span class="banner-word"></span>'
  arena.appendChild(banner)
}

function railHtml(f, side) {
  const fam = familyInfo(f.family)
  const fam2 = f.family2 ? familyInfo(f.family2) : null
  return `
    <div class="hud-top">
      <div class="hud-portrait"></div>
      <div class="hud-id">
        <span class="hud-name">${f.resonant ? '<span style="color:#d9ad62">◈</span> ' : ''}${f.name}</span>
        <span class="hud-family">${fam.name}${fam2 ? ' / ' + fam2.name : ''} · ${f.role}</span>
      </div>
    </div>
    <div class="hud-bars">
      <div class="hp-track"><div class="hp-fill"></div><div class="shield-fill" style="display:none"></div></div>
      <div class="hud-num"><span>HP</span><span><b>${Math.ceil(f.hp)}</b> / ${f.maxHp}</span></div>
      <div class="energy-track"><div class="energy-fill"></div></div>
    </div>`
}

function renderRail(lane, side) {
  const f = side === 'ally' ? lane.ally : lane.enemy
  const el = lane.el.querySelector(`.lane-hud[data-side="${side}"]`)
  el.innerHTML = railHtml(f, side)
  const canvas = document.createElement('canvas')
  el.querySelector('.hud-portrait').appendChild(canvas)
  import('./creature.js').then(m => m.renderPortrait(canvas, f, { size: 84, ring: false, showPedestal: false }))
  lane.hud[side] = {
    el,
    hp: el.querySelector('.hp-fill'),
    shield: el.querySelector('.shield-fill'),
    num: el.querySelector('.hud-num'),
    energy: el.querySelector('.energy-fill'),
    name: el.querySelector('.hud-name'),
  }
}

function layoutLanes() {
  if (!state.battle) return
  const bl = state.battle
  bl.lanes.forEach(lane => {
    if (!lane.el.isConnected) return
    const rect = lane.el.getBoundingClientRect()
    if (rect.width < 20 || rect.height < 20) return
    lane.W = rect.width
    lane.H = rect.height
    lane.dpr = Math.min(window.devicePixelRatio || 1, 2)
    lane.canvas.width = Math.round(lane.W * lane.dpr)
    lane.canvas.height = Math.round(lane.H * lane.dpr)
    lane.canvas.style.width = lane.W + 'px'
    lane.canvas.style.height = lane.H + 'px'
    lane.bgCanvas = buildLaneBackground(lane)
  })
}

window.addEventListener('resize', () => {
  clearTimeout(resizeTimer)
  resizeTimer = setTimeout(layoutLanes, 120)
})

// ───────────────────────────── commands ─────────────────────────────
function buildCommands(bl) {
  const wrap = $('#cmdWrap')
  wrap.innerHTML = ''
  for (const c of COMMANDS) {
    const btn = document.createElement('button')
    btn.className = 'cmd'
    btn.dataset.cmd = c.id
    btn.innerHTML = `
      <span class="cmd-icon">${c.icon}</span>
      <span class="cmd-copy">
        <span class="cmd-name">${c.name}<span class="cmd-key">${c.key}</span>${c.id === 'shift' ? '<span class="charge-dot"></span><span class="shift-count"></span>' : ''}</span>
        <span class="cmd-desc">${c.desc}</span>
      </span>
      <span class="cd-sweep"></span>
      <span class="cd-label"></span>`
    btn.addEventListener('click', () => triggerCommand(c.id))
    wrap.appendChild(btn)
  }
  const hint = $('#commandHint')
  hint.classList.remove('targeting')
  $('#hintText').textContent = 'Abilities charge as your chimeras strike. Commands are yours alone.'
  updateCommandBar(bl, true)
  updateScorePips(bl)
  setPhaseText('THE HORN SOUNDS')
}

function updateCommandBar(bl, force = false) {
  if (!bl) return
  for (const c of COMMANDS) {
    const btn = document.querySelector(`.cmd[data-cmd="${c.id}"]`)
    if (!btn) continue
    const cmd = bl.commands[c.id]
    const remain = c.id === 'shift' ? 0 : Math.max(0, cmd.remain)
    const cooling = remain > 0.05
    const active = bl.mode && bl.mode.type === c.id
    const spent = c.id === 'shift' && bl.shiftCharges <= 0
    btn.classList.toggle('cooling', cooling)
    btn.classList.toggle('active', !!active)
    btn.classList.toggle('spent', spent)
    btn.disabled = bl.phase !== 'fight' || cooling || spent || bl.ended
    const sweep = btn.querySelector('.cd-sweep')
    if (sweep) sweep.style.height = cooling ? `${Math.min(100, (remain / cmd.max) * 100)}%` : '0%'
    const label = btn.querySelector('.cd-label')
    if (label) label.textContent = cooling ? Math.ceil(remain) : ''
    if (c.id === 'shift') {
      const sc = btn.querySelector('.shift-count')
      if (sc) sc.textContent = `${bl.shiftCharges}`
    }
  }
  const hint = $('#commandHint')
  const hintText = $('#hintText')
  if (!hint || !hintText) return
  hint.classList.toggle('targeting', !!bl.mode)
  if (bl.mode?.type === 'starfall') hintText.textContent = 'STARFALL — choose a lane (click or press 1–5). Esc cancels.'
  else if (bl.mode?.type === 'swap') hintText.textContent = bl.mode.first == null ? 'SHIFT — choose the first fighter.' : 'SHIFT — choose the second fighter. Esc cancels.'
  else hintText.textContent = 'Abilities charge as your chimeras strike. Commands are yours alone.'
}

function triggerCommand(id) {
  const bl = state.battle
  if (!bl || bl.phase !== 'fight' || bl.ended) return
  const cmd = bl.commands[id]
  if (id !== 'shift' && cmd.remain > 0) return
  if (bl.mode?.type === id) { clearMode(); return }
  if (id === 'rally') {
    if (cmd.remain > 0) return
    castRally(bl)
  } else if (id === 'aegis') {
    if (cmd.remain > 0) return
    castAegis(bl)
  } else if (id === 'starfall') {
    if (cmd.remain > 0) return
    setMode(bl, { type: 'starfall' })
  } else if (id === 'shift') {
    if (bl.shiftCharges <= 0) return
    setMode(bl, { type: 'swap', first: null })
  }
}

function setMode(bl, mode) {
  bl.mode = mode
  bl.lanes.forEach(lane => lane.el.classList.remove('targeting', 'swap-first'))
  if (mode?.type === 'starfall') {
    bl.lanes.forEach(lane => {
      if (!lane.resolved && !lane.enemy.dead) lane.el.classList.add('targeting')
    })
  }
  updateCommandBar(bl)
  sound.click()
}

function clearMode() {
  const bl = state.battle
  if (!bl) return
  bl.mode = null
  bl.lanes.forEach(lane => lane.el.classList.remove('targeting', 'swap-first'))
  updateCommandBar(bl)
}

function laneClicked(index) {
  const bl = state.battle
  if (!bl || bl.phase !== 'fight' || bl.ended) return
  if (!bl.mode) return
  if (bl.mode.type === 'starfall') {
    castStarfall(bl, index)
  } else if (bl.mode.type === 'swap') {
    handleSwapClick(bl, index)
  }
}

function handleSwapClick(bl, index) {
  const lane = bl.lanes[index]
  if (lane.resolved || lane.phase !== 'fight' || lane.ally.dead) {
    toast('That fighter cannot answer the call.', true)
    return
  }
  if (bl.mode.first == null) {
    bl.mode.first = index
    lane.el.classList.add('swap-first')
    updateCommandBar(bl)
    return
  }
  if (bl.mode.first === index) {
    bl.mode.first = null
    lane.el.classList.remove('swap-first')
    updateCommandBar(bl)
    return
  }
  shiftLanes(bl, bl.mode.first, index)
}

function shiftLanes(bl, i, j) {
  const a = bl.lanes[i], b = bl.lanes[j]
  const fa = a.ally, fb = b.ally
  a.ally = fb
  b.ally = fa
  for (const [lane, f] of [[a, fb], [b, fa]]) {
    f.x = 0.18
    f.attackTimer = Math.max(f.attackTimer, 0.5)
    f.status.stunUntil = 0
    f.status.slowUntil = 0
    lane.el.classList.remove('lane-won-ally', 'lane-won-enemy')
    renderRail(lane, 'ally')
    spawnRing(lane, 0.18, 0.84, 40, 130, '#d8b4ff', 0.5)
    spawnParticles(lane, 0.18, 0.84, '#d8b4ff', 18, 1)
  }
  bl.shiftCharges -= 1
  bl.mode = null
  bl.lanes.forEach(l => l.el.classList.remove('targeting', 'swap-first'))
  updateCommandBar(bl)
  toast('The veil folds — fighters shifted.')
  sound.cast()
}

// ───────────────────────────── command effects ─────────────────────────────
function castRally(bl) {
  bl.commands.rally.remain = bl.commands.rally.max
  for (const lane of bl.lanes) {
    if (lane.resolved || lane.ally.dead) continue
    lane.ally.status.aspdUntil = bl.t + 5
    lane.ally.status.aspdMult = 1.35
    spawnRing(lane, lane.ally.x, 0.84, 20, 95, '#f6d48a', 0.6)
    spawnParticles(lane, lane.ally.x, 0.82, '#f6d48a', 12, 0.8)
    floatText(lane, lane.ally.x, 0.64, 'RALLY', '#f8d995', 1.4, true)
  }
  toast('Rally — the five answer as one.')
  sound.cast()
  updateCommandBar(bl)
}

function castAegis(bl) {
  bl.commands.aegis.remain = bl.commands.aegis.max
  for (const lane of bl.lanes) {
    if (lane.resolved || lane.ally.dead) continue
    lane.ally.shield += lane.ally.maxHp * 0.30 * (lane.ally.shieldPower || 1)
    spawnRing(lane, lane.ally.x, 0.84, 30, 120, '#8ed8ff', 0.7)
    spawnParticles(lane, lane.ally.x, 0.7, '#9ee6ff', 14, 0.6)
    floatText(lane, lane.ally.x, 0.6, 'AEGIS', '#a8e5ff', 1.4, true)
  }
  toast('Aegis — a second hide of light.')
  sound.cast()
  updateCommandBar(bl)
}

function castStarfall(bl, laneIndex) {
  const lane = bl.lanes[laneIndex]
  if (!lane || lane.resolved || lane.enemy.dead) {
    toast('No living foe in that lane.', true)
    return
  }
  const allies = bl.lanes.filter(l => !l.ally.dead).map(l => l.ally)
  const avg = allies.length ? allies.reduce((s, f) => s + f.atk, 0) / allies.length : 70
  const raw = avg * 3.4 * state.runMods.starfall
  addMeteor(lane, lane.enemy.x, 0.82, 0.75)
  bl.commands.starfall.remain = bl.commands.starfall.max
  // Impact after the meteor falls.
  lane.fx.pendingMeteor = { at: bl.t + 0.38, raw, target: lane.enemy, source: allies[0] || lane.ally }
  bl.mode = null
  bl.lanes.forEach(l => l.el.classList.remove('targeting', 'swap-first'))
  updateCommandBar(bl)
  toast('Starfall — the sky answers.')
  sound.cast()
}

