// ───────────────────────────── background ─────────────────────────────
function buildLaneBackground(lane) {
  const { W, H, dpr, index } = lane
  const terr = TERRAINS[index]
  const c = document.createElement('canvas')
  c.width = Math.round(W * dpr)
  c.height = Math.round(H * dpr)
  const x = c.getContext('2d')
