  cg.addColorStop(0.55, hexA(terr.color, 0.035))
  cg.addColorStop(1, hexA(terr.color, 0))
  x.fillStyle = cg
  x.fillRect(0, 0, W, H)

  // gate glows
  for (const [gx, color] of [[-0.02, '#81d7ff'], [1.02, '#ff8b78']]) {
