  x.strokeStyle = hexA(terr.color, 0.12)
  x.lineWidth = 1
  x.beginPath(); x.arc(0, 0, base, 0, Math.PI * 2); x.stroke()
  x.setLineDash([4, 9])
  x.strokeStyle = hexA(terr.color, 0.10)
  x.beginPath(); x.arc(0, 0, base * 1.34, 0, Math.PI * 2); x.stroke()
  x.setLineDash([])
