  x.strokeStyle = 'rgba(200,215,240,.045)'
  x.lineWidth = 1
  for (let i = 1; i < 10; i++) {
    const px = W * i / 10
    x.beginPath(); x.moveTo(px, H * 0.2); x.lineTo(px, H * 0.88); x.stroke()
  }

