    const { state } = await import('/js/core.js')
    state.battle.introT = 0.05
    state.battle.score.ally = 3
    state.battle.time = 0.001
  })
  await page.waitForTimeout(2300)
}
;(async () => {
  const browser = await chromium.launch({ headless: true, args: ['--no-sandbox'] })
  const page = await browser.newPage({ viewport: { width: 1280, height: 800 } })
  const errs=[]
  page.on('pageerror', e => { errs.push(e.message); console.log('PAGEERROR', e.message) })
  page.on('console', m => { if (m.type() === 'error') { errs.push(m.text()); console.log('CONSOLE', m.text()) } })
  await page.goto('http://127.0.0.1:3002/', { waitUntil: 'networkidle' })
  await page.waitForTimeout(300)
  await page.evaluate(async () => {
    const core = await import('/js/core.js')
    const { state } = core
    state.fighters = [0,1,2,3,4].map(i => core.makeChimera('wolf','phoenix',{laneIndex:i,isPlayer:true}))
    const prep = await import('/js/prep.js'); prep.renderPrep()
  })
  for (let round=1; round<=5; round++) {
    await page.click('#battleBtn'); await page.waitForTimeout(250)
    await forceWin(page)
    const title = await page.locator('.overlay-title').textContent().catch(()=>'none')
    console.log('round', round, 'overlay:', title)
    if (title === 'ASCENDANT') {
      await page.screenshot({ path: '/tmp/opencode/shots/17-final-victory.jpg', type: 'jpeg', quality: 84 })
      break
    }
    await page.click('[data-action="boons"]'); await page.waitForTimeout(350)
    const names = await page.locator('.boon-name').allTextContents()
    console.log('  boons:', names.join(' | '))
    await page.locator('.boon-card').first().click(); await page.waitForTimeout(600)
    const st = await page.evaluate(async () => { const { state } = await import('/js/core.js'); return { round: state.round, title: document.querySelector('#roundTitle').textContent, aether: state.aether, boons: state.boons.length, pips: [...document.querySelectorAll('.round-pip')].map(p=>p.className) } })
    console.log('  after boon:', JSON.stringify(st))
  }
  console.log('errors:', errs.length)
  await browser.close()
})().catch(e=>{console.error(e);process.exit(1)})
