const { createRequire } = require('node:module')
const runtime = process.env.HOME + '/.local/share/omgithub-playwright'
const require2 = createRequire(runtime + '/package.json')
const { chromium } = require2('playwright')
;(async () => {
  const browser = await chromium.launch({ headless: true, args: ['--no-sandbox'] })
  const page = await browser.newPage({ viewport: { width: 1280, height: 800 } })
  page.on('pageerror', e => console.log('PAGEERROR', e.message))
  page.on('console', m => { if (m.type() === 'error') console.log('CONSOLE', m.text()) })
  await page.goto('http://127.0.0.1:3002/', { waitUntil: 'networkidle' })
  await page.waitForTimeout(300)
  await page.click('#infoBtn'); await page.waitForTimeout(300)
  console.log('modal visible:', await page.locator('#modalRoot').isVisible())
  await page.screenshot({ path: '/tmp/opencode/shots/18-info-modal.jpg', type: 'jpeg', quality: 84 })
  await page.keyboard.press('Escape'); await page.waitForTimeout(200)
  console.log('modal closed:', !(await page.locator('#modalRoot').isVisible()))
  await page.evaluate(async () => {
    const core = await import('/js/core.js'); const { state } = core
    state.fighters = [0,1,2,3,4].map(i => core.makeChimera('wolf','phoenix',{laneIndex:i,isPlayer:true}))
    const prep = await import('/js/prep.js'); prep.renderPrep()
  })
  await page.click('#battleBtn'); await page.waitForTimeout(200)
  await page.evaluate(async () => { const { state } = await import('/js/core.js'); state.battle.introT = 0.05 })
  await page.waitForTimeout(600)
  const t1 = await page.evaluate(async () => (await import('/js/core.js')).state.battle.t)
  await page.click('#infoBtn'); await page.waitForTimeout(1000)
  const t2 = await page.evaluate(async () => (await import('/js/core.js')).state.battle.t)
  await page.keyboard.press('Escape'); await page.waitForTimeout(700)
  const t3 = await page.evaluate(async () => (await import('/js/core.js')).state.battle.t)
  console.log('pause t:', t1.toFixed(2), t2.toFixed(2), 'resumed:', t3.toFixed(2))
  await browser.close()
})().catch(e=>{console.error(e);process.exit(1)})
